def _normalize_warning_source_text(text: str) -> str:
    return " ".join(strip_r_comment(text).strip().split())


def _warning_line_for_current_stmt() -> tuple[int, str] | None:
    if not _WARNING_SOURCE_TEXT or not _CURRENT_WARNING_STMT_TEXT:
        return None
    target = _normalize_warning_source_text(_CURRENT_WARNING_STMT_TEXT)
    if not target:
        return None
    target_l = target.lower()
    for i, raw in enumerate(_WARNING_SOURCE_TEXT.splitlines(), start=1):
        code = _normalize_warning_source_text(raw)
        if not code:
            continue
        code_l = code.lower()
        if code_l == target_l or target_l in code_l or code_l in target_l:
            return i, code
    return None


def _warning_line_for_literal(lit: str) -> tuple[int, str] | None:
    if not _WARNING_SOURCE_TEXT:
        return None
    raw_lit = lit.strip()
    candidates = {raw_lit}
    candidates.add(re.sub(r"_dp\b", "", raw_lit, flags=re.IGNORECASE))
    candidates.add(raw_lit.replace("D", "E").replace("d", "e"))
    for i, raw in enumerate(_WARNING_SOURCE_TEXT.splitlines(), start=1):
        code = _normalize_warning_source_text(raw)
        if not code:
            continue
        if any(c and c in code for c in candidates):
            return i, code
    return None


def _warning_stmt_source_text(st: object) -> str | None:
    if isinstance(st, Assign):
        return f"{st.name} = {st.expr}"
    if isinstance(st, PrintStmt):
        return "print(" + ", ".join(st.args) + ")"
    if isinstance(st, CallStmt):
        return f"{st.name}(" + ", ".join(st.args) + ")"
    if isinstance(st, ExprStmt):
        return st.expr
    if isinstance(st, ForStmt):
        return f"for ({st.var} in {st.iter_expr})"
    if isinstance(st, WhileStmt):
        return f"while ({st.cond})"
    if isinstance(st, IfStmt):
        return f"if ({st.cond})"
    return None


def _emit_warning(msg: str) -> None:
    if not _SUPPRESS_WARNINGS:
        loc = _warning_line_for_current_stmt()
        if loc is not None and " at R line " not in msg:
            line_no, code = loc
            msg = f"{msg} at R line {line_no}: {code}"
        print(msg)


def _expanded_data_frame_col_expr(obj: str, field: str) -> str | None:
    fields = _EXPANDED_DATA_FRAME_FIELDS.get(obj)
    aliases = _EXPANDED_DATA_FRAME_ALIASES.get(obj)
    if fields is None:
        fields = _EXPANDED_DATA_FRAME_FIELDS.get(obj.lower())
        aliases = _EXPANDED_DATA_FRAME_ALIASES.get(obj.lower())
    if fields is None:
        return None
    field_l = field.lower()
    if field_l not in {f.lower() for f in fields}:
        return None
    if aliases is not None:
        for k, v in aliases.items():
            if k.lower() == field_l:
                return v
    return f"{obj}_{_sanitize_fortran_kwarg_name(field)}"


@dataclass
class Assign:
    name: str
    expr: str
    comment: str = ""


@dataclass
class PrintStmt:
    args: list[str]
    comment: str = ""


@dataclass
class ForStmt:
    var: str
    iter_expr: str
    body: list[object]


@dataclass
class WhileStmt:
    cond: str
    body: list[object]


@dataclass
class RepeatStmt:
    body: list[object]


@dataclass
class IfStmt:
    cond: str
    then_body: list[object]
    else_body: list[object]


@dataclass
class SwitchStmt:
    selector: str
    cases: list[tuple[str, list[object]]]
    default_body: list[object]
    selector_kind: str = "character"


@dataclass
class CallStmt:
    name: str
    args: list[str]
    comment: str = ""


@dataclass
class ExprStmt:
    expr: str
    comment: str = ""


@dataclass
class CommentStmt:
    text: str


@dataclass
class FuncDef:
    name: str
    args: list[str]
    defaults: dict[str, str]
    body: list[object]
    leading_comments: tuple[str, ...] = ()


@dataclass
class SymbolInfo:
    rank: int = 0
    kind: str | None = None


def _fortran_comment_payload(text: str) -> str | None:
    if not _FORTRAN_COMMENTS:
        return None
    t = text.lstrip()
    m = re.match(r"^(?:f|fortran)\s+(.+)$", t, flags=re.IGNORECASE)
    if not m:
        return None
    payload = m.group(1).rstrip()
    p = payload.lstrip().lower()
    if re.match(
        r"^(?:print|write|read|call|if|do|end|else|where|forall|associate|block|allocate|deallocate|"
        r"integer|real|logical|character|complex|type|class|use|implicit|contains|return|cycle|exit|stop|error\s+stop)\b",
        p,
    ) or re.match(r"^[A-Za-z]\w*(?:\([^)]*\))?\s*=", payload):
        return payload
    return None


def _collect_stmt_expr_texts(stmts: list[object]) -> list[str]:
    out: list[str] = []
    for st in stmts:
        if isinstance(st, Assign):
            out.append(st.expr)
        elif isinstance(st, PrintStmt):
            out.extend(st.args)
        elif isinstance(st, ForStmt):
            out.append(st.iter_expr)
            out.extend(_collect_stmt_expr_texts(st.body))
        elif isinstance(st, IfStmt):
            out.append(st.cond)
            out.extend(_collect_stmt_expr_texts(st.then_body))
            out.extend(_collect_stmt_expr_texts(st.else_body))
        elif isinstance(st, WhileStmt):
            out.append(st.cond)
            out.extend(_collect_stmt_expr_texts(st.body))
        elif isinstance(st, RepeatStmt):
            out.extend(_collect_stmt_expr_texts(st.body))
        elif isinstance(st, SwitchStmt):
            out.append(st.selector)
            for _case_expr, case_body in st.cases:
                out.extend(_collect_stmt_expr_texts(case_body))
            out.extend(_collect_stmt_expr_texts(st.default_body))
        elif isinstance(st, CallStmt):
            out.extend(st.args)
        elif isinstance(st, ExprStmt):
            out.append(st.expr)
    return out


def _collect_stmt_assigned_names(stmts: list[object]) -> set[str]:
    out: set[str] = set()
    for st in stmts:
        if isinstance(st, Assign):
            out.add(st.name.lower())
        elif isinstance(st, ForStmt):
            out.add(st.var.lower())
            out.update(_collect_stmt_assigned_names(st.body))
        elif isinstance(st, IfStmt):
            out.update(_collect_stmt_assigned_names(st.then_body))
            out.update(_collect_stmt_assigned_names(st.else_body))
        elif isinstance(st, WhileStmt):
            out.update(_collect_stmt_assigned_names(st.body))
        elif isinstance(st, RepeatStmt):
            out.update(_collect_stmt_assigned_names(st.body))
        elif isinstance(st, SwitchStmt):
            for _case_expr, case_body in st.cases:
                out.update(_collect_stmt_assigned_names(case_body))
            out.update(_collect_stmt_assigned_names(st.default_body))
    return out


def _infer_function_free_names(fn: FuncDef) -> set[str]:
    locals_l = {a.lower() for a in fn.args}
    locals_l.update(_collect_stmt_assigned_names(fn.body))
    refs_l: set[str] = set()
    for txt in _collect_stmt_expr_texts(fn.body):
        dotted_spans: list[tuple[int, int]] = []
        for m_dot in re.finditer(r"\b[A-Za-z]\w*(?:\.[A-Za-z]\w*)+\b", txt):
            refs_l.add(m_dot.group(0).lower())
            dotted_spans.append(m_dot.span())
        for m_name in re.finditer(r"\b[A-Za-z]\w*\b", txt):
            if any(a <= m_name.start() and m_name.end() <= b for a, b in dotted_spans):
                continue
            refs_l.add(m_name.group(0).lower())
    # Conservative filter of obvious non-variable tokens.
    ignore = {
        "true", "false", "na", "nan", "null", "inf",
        "if", "else", "for", "while", "function", "in",
        "sum", "mean", "sd", "var", "sqrt", "log", "exp",
        "abs", "sin", "cos", "tan", "asin", "acos", "atan",
        "min", "max", "pmin", "pmax", "quantile", "dnorm",
        "runif", "rnorm", "sample", "sample.int", "length",
        "matrix", "array", "cbind", "crossprod", "tcrossprod",
        "t", "print", "cat", "paste", "paste0",
    }
    refs_l = {r for r in refs_l if r not in ignore}
    refs_l.discard(fn.name.lower())
    return {r for r in refs_l if r not in locals_l}


def _lift_nested_functions(stmts: list[object]) -> list[object]:
    """Lift nested R functions to top-level helpers with closure vars as arguments."""

    def split_nested_defs(body: list[object]) -> tuple[list[object], list[FuncDef]]:
        cleaned: list[object] = []
        nested: list[FuncDef] = []
        for b in body:
            if isinstance(b, FuncDef):
                nested.append(b)
            elif isinstance(b, ForStmt):
                new_body, body_nested = split_nested_defs(b.body)
                nested.extend(body_nested)
                cleaned.append(ForStmt(b.var, b.iter_expr, new_body))
            elif isinstance(b, WhileStmt):
                new_body, body_nested = split_nested_defs(b.body)
                nested.extend(body_nested)
                cleaned.append(WhileStmt(b.cond, new_body))
            elif isinstance(b, RepeatStmt):
                new_body, body_nested = split_nested_defs(b.body)
                nested.extend(body_nested)
                cleaned.append(RepeatStmt(new_body))
            elif isinstance(b, IfStmt):
                then_body, then_nested = split_nested_defs(b.then_body)
                else_body, else_nested = split_nested_defs(b.else_body)
                nested.extend(then_nested)
                nested.extend(else_nested)
                cleaned.append(IfStmt(b.cond, then_body, else_body))
            elif isinstance(b, SwitchStmt):
                cases: list[tuple[str, list[object]]] = []
                for case_expr, case_body in b.cases:
                    new_case_body, case_nested = split_nested_defs(case_body)
                    nested.extend(case_nested)
                    cases.append((case_expr, new_case_body))
                default_body, default_nested = split_nested_defs(b.default_body)
                nested.extend(default_nested)
                cleaned.append(SwitchStmt(b.selector, cases, default_body, b.selector_kind))
            else:
                cleaned.append(b)
        return cleaned, nested

    def rewrite_expr(expr: str, call_map: dict[str, tuple[str, list[str]]]) -> str:
        out = _lower_r_native_pipe_expr(expr)
        for old, (new, captures) in sorted(call_map.items(), key=lambda kv: len(kv[0]), reverse=True):
            def repl(inner: str, new_name: str = new, caps: list[str] = captures) -> str:
                pos = split_top_level_commas(inner) if inner.strip() else []
                args = [p.strip() for p in pos if p.strip()] + caps
                return f"{new_name}(" + ", ".join(args) + ")"

            out = _replace_balanced_func_calls(out, old, repl)
        return out

    def rewrite_stmt(st: object, call_map: dict[str, tuple[str, list[str]]]) -> object:
        if isinstance(st, Assign):
            return Assign(st.name, rewrite_expr(st.expr, call_map), st.comment)
        if isinstance(st, ExprStmt):
            return ExprStmt(rewrite_expr(st.expr, call_map), st.comment)
        if isinstance(st, PrintStmt):
            return PrintStmt([rewrite_expr(a, call_map) for a in st.args], st.comment)
        if isinstance(st, CallStmt):
            return CallStmt(st.name, [rewrite_expr(a, call_map) for a in st.args], st.comment)
        if isinstance(st, ForStmt):
            return ForStmt(st.var, rewrite_expr(st.iter_expr, call_map), [rewrite_stmt(b, call_map) for b in st.body])
        if isinstance(st, WhileStmt):
            return WhileStmt(rewrite_expr(st.cond, call_map), [rewrite_stmt(b, call_map) for b in st.body])
        if isinstance(st, RepeatStmt):
            return RepeatStmt([rewrite_stmt(b, call_map) for b in st.body])
        if isinstance(st, IfStmt):
            return IfStmt(
                rewrite_expr(st.cond, call_map),
                [rewrite_stmt(b, call_map) for b in st.then_body],
                [rewrite_stmt(b, call_map) for b in st.else_body],
            )
        return st

    out: list[object] = []
    for st in stmts:
        if not isinstance(st, FuncDef):
            out.append(st)
            continue
        body, nested = split_nested_defs(st.body)
        if not nested:
            out.append(st)
            continue
        parent_names = list(st.args)
        parent_names.extend(sorted(_collect_stmt_assigned_names(body)))
        parent_by_lower = {nm.lower(): nm for nm in parent_names}
        for nm in parent_names:
            if "_" in nm:
                parent_by_lower.setdefault(nm.replace("_", ".").lower(), nm)
        nested_names = {nf.name.lower() for nf in nested}
        call_map: dict[str, tuple[str, list[str]]] = {}
        lifted: list[object] = []
        for nf in nested:
            free = _infer_function_free_names(nf)
            capture_matches = [
                (nm_l, parent_by_lower[nm_l])
                for nm_l in parent_by_lower
                if nm_l in free and nm_l not in nested_names
            ]
            raw_captures = [parent_nm for _free_nm, parent_nm in capture_matches]
            captures = [_sanitize_fortran_kwarg_name(nm) for nm in raw_captures]
            capture_rename: dict[str, str] = {}
            for (free_nm, parent_nm), san in zip(capture_matches, captures):
                if free_nm != san:
                    capture_rename[free_nm] = san
                if parent_nm != san:
                    capture_rename[parent_nm] = san
            new_name = f"{st.name}_{nf.name}"
            call_map[nf.name] = (new_name, captures)
            lifted.append(
                FuncDef(
                    name=new_name,
                    args=list(nf.args) + captures,
                    defaults=dict(nf.defaults),
                    body=[_rename_stmt_obj(b, capture_rename) for b in nf.body] if capture_rename else list(nf.body),
                    leading_comments=nf.leading_comments,
                )
            )
        rewritten_lifted: list[object] = []
        for lf in lifted:
            if not isinstance(lf, FuncDef):
                rewritten_lifted.append(lf)
                continue
            old_name = next(
                (
                    old
                    for old, (new_name_for_old, _captures_for_old) in call_map.items()
                    if new_name_for_old.lower() == lf.name.lower()
                ),
                None,
            )
            body_call_map = {
                old: spec
                for old, spec in call_map.items()
                if spec[0].lower() != lf.name.lower()
            }
            rewritten_body = [rewrite_stmt(b, body_call_map) for b in lf.body]
            lifted_args = list(lf.args)
            if old_name is not None:
                free_after_rewrite: set[str] = set()
                tmp_free_fn = FuncDef(
                    name=lf.name,
                    args=lifted_args,
                    defaults=dict(lf.defaults),
                    body=rewritten_body,
                    leading_comments=lf.leading_comments,
                )
                free_after_rewrite = _infer_function_free_names(tmp_free_fn)
                extra_captures: list[str] = []
                for free_nm_l, parent_nm in parent_by_lower.items():
                    if free_nm_l not in free_after_rewrite or free_nm_l in nested_names:
                        continue
                    san_nm = _sanitize_fortran_kwarg_name(parent_nm)
                    if not any(arg.lower() == san_nm.lower() for arg in lifted_args + extra_captures):
                        extra_captures.append(san_nm)
                if extra_captures:
                    lifted_args.extend(extra_captures)
                    new_name, captures = call_map[old_name]
                    call_map[old_name] = (new_name, captures + extra_captures)
            rewritten_lifted.append(
                FuncDef(
                    name=lf.name,
                    args=lifted_args,
                    defaults=dict(lf.defaults),
                    body=rewritten_body,
                    leading_comments=lf.leading_comments,
                )
            )
        out.extend(_lift_nested_functions(rewritten_lifted))
        out.append(
            FuncDef(
                name=st.name,
                args=list(st.args),
                defaults=dict(st.defaults),
                body=[rewrite_stmt(b, call_map) for b in body],
                leading_comments=st.leading_comments,
            )
        )
    return out


def helper_modules_from_files(paths: list[Path]) -> set[str]:
    """Extract top-level module names from helper Fortran files."""
    mods: set[str] = set()
    m_re = re.compile(r"^\s*module\s+([a-z][a-z0-9_]*)\b", re.IGNORECASE)
    end_re = re.compile(r"^\s*end\s+module\b", re.IGNORECASE)
    proc_re = re.compile(r"^\s*module\s+procedure\b", re.IGNORECASE)
    for p in paths:
        try:
            txt = p.read_text(encoding="utf-8")
        except Exception:
            txt = p.read_text(encoding="utf-8", errors="replace")
        for ln in txt.splitlines():
            s = ln.strip()
            if not s:
                continue
            if end_re.match(s) or proc_re.match(s):
                continue
            m = m_re.match(s)
            if m:
                mods.add(m.group(1).lower())
    return mods


def _wrapped_public_line(names: set[str]) -> list[str]:
    unique: dict[str, str] = {}
    for nm in sorted(names):
        unique.setdefault(nm.lower(), nm)
    vals = list(unique.values())
    if not vals:
        return []
    out: list[str] = []
    cur = "public :: "
    for i, nm in enumerate(vals):
        piece = nm if cur.endswith(":: ") else ", " + nm
        if len(cur + piece) > 88:
            out.append(cur + ", &")
            cur = "   & " + nm
        else:
            cur += piece
    out.append(cur)
    return out


def add_private_publics_to_generated_modules_text(f90: str) -> str:
    """Make generated modules private by default and publicize used module entities."""
    if not EMIT_PRIVATE_MODULE_PUBLICS:
        return f90
    lines = f90.splitlines()
    modules: list[dict[str, object]] = []
    i = 0
    while i < len(lines):
        m = re.match(r"^\s*module\s+([A-Za-z]\w*)\s*$", lines[i], re.IGNORECASE)
        if m is None:
            i += 1
            continue
        mod_name = m.group(1)
        if mod_name.lower() == "r_mod":
            i += 1
            continue
        end_i = next((j for j in range(i + 1, len(lines)) if re.match(r"^\s*end\s+module\b", lines[j], re.IGNORECASE)), -1)
        if end_i < 0:
            i += 1
            continue
        contains_i = next((j for j in range(i + 1, end_i) if re.match(r"^\s*contains\s*$", lines[j], re.IGNORECASE)), end_i)
        modules.append({"name": mod_name, "start": i, "contains": contains_i, "end": end_i})
        i = end_i + 1
    if not modules:
        return f90

    text = "\n".join(lines)
    first_program_i = next((j for j, ln in enumerate(lines) if re.match(r"^\s*program\b", ln, re.IGNORECASE)), len(lines))
    program_text = "\n".join(lines[first_program_i:])
    used_by_module: dict[str, set[str]] = {}
    for mod in modules:
        mod_name = str(mod["name"])
        used: set[str] = set()
        for um in re.finditer(rf"(?im)^\s*use\s+{re.escape(mod_name)}\s*(?:,\s*only\s*:\s*(.*))?$", text):
            only = (um.group(1) or "").strip()
            if only:
                for part in split_top_level_commas(only):
                    nm = part.split("=>", 1)[-1].strip()
                    if re.match(r"^[A-Za-z]\w*$", nm):
                        used.add(nm)
        used_by_module[mod_name.lower()] = used

    out = list(lines)
    offset = 0
    for mod in modules:
        mod_name = str(mod["name"])
        start = int(mod["start"]) + offset
        contains = int(mod["contains"]) + offset
        end = int(mod["end"]) + offset
        header_range = out[start + 1 : contains]
        if any(re.match(r"^\s*private\s*$", ln, re.IGNORECASE) for ln in header_range):
            continue
        public_names = set(used_by_module.get(mod_name.lower(), set()))
        for ln in out[contains + 1 : end]:
            fm = re.match(r"^\s*(?:pure\s+|elemental\s+|recursive\s+)*(?:function|subroutine)\s+([A-Za-z]\w*)\b", ln, re.IGNORECASE)
            if fm is not None:
                public_names.add(fm.group(1))
        for ln in header_range:
            tm = re.match(r"^\s*type\s*(?:,\s*[^:]*)?::\s*([A-Za-z]\w*)\b", ln, re.IGNORECASE)
            if tm is not None:
                public_names.add(tm.group(1))
            pm = re.match(r"^\s*(?:integer|real\s*\([^)]*\)|logical|complex\s*\([^)]*\)|character\s*\([^)]*\))\s*,\s*parameter\s*::\s*(.+)$", ln, re.IGNORECASE)
            if pm is not None:
                for part in split_top_level_commas(pm.group(1)):
                    nm_m = re.match(r"\s*([A-Za-z]\w*)\b", part)
                    if nm_m is not None:
                        public_names.add(nm_m.group(1))
        header_top_level = re.sub(
            r"(?ims)^\s*type(?:\s*,[^:]*)?\s*::\s*[A-Za-z]\w*\b.*?^\s*end\s+type\b[^\n]*",
            "",
            "\n".join(header_range),
        )
        flat_header = re.sub(r"&\s*\n\s*&?\s*", " ", header_top_level)
        for dm in re.finditer(
            r"(?im)^\s*(?:real\s*\([^)]*\)|integer|logical|complex\s*\([^)]*\)|character\s*(?:\([^)]*\))?)(?:\s*,\s*[^:]*)?::\s*(.+)$",
            flat_header,
        ):
            if re.search(r"\bparameter\b", dm.group(0), re.IGNORECASE):
                continue
            for part in split_top_level_commas(dm.group(1)):
                nm_m = re.match(r"\s*([A-Za-z]\w*)\b", part)
                if nm_m is None:
                    continue
                nm = nm_m.group(1)
                if re.search(rf"\b{re.escape(nm)}\b", program_text):
                    public_names.add(nm)
        insert_at = start + 1
        while insert_at < contains:
            line = out[insert_at]
            if re.match(r"^\s*use\b", line, re.IGNORECASE):
                insert_at += 1
                while insert_at < contains and out[insert_at - 1].rstrip().endswith("&"):
                    insert_at += 1
                continue
            if re.match(r"^\s*implicit\s+none\b", line, re.IGNORECASE):
                insert_at += 1
                continue
            if line.lstrip().startswith("&"):
                insert_at += 1
                continue
            break
        insert_lines = ["private"] + _wrapped_public_line(public_names)
        out[insert_at:insert_at] = insert_lines
        offset += len(insert_lines)
    return "\n".join(out) + ("\n" if f90.endswith("\n") else "")


def declare_missing_matrix_aliases_text(f90: str) -> str:
    """Declare simple matrix aliases assigned from already-declared matrices."""
    lines = f90.splitlines()
    out = list(lines)
    i = 0
    offset = 0
    while i < len(lines):
        start_m = re.match(r"^\s*(?:program|(?:pure\s+|elemental\s+|recursive\s+)*function|subroutine)\b", lines[i], re.IGNORECASE)
        if start_m is None:
            i += 1
            continue
        end_i = next((j for j in range(i + 1, len(lines)) if re.match(r"^\s*end\s+(?:program|function|subroutine)\b", lines[j], re.IGNORECASE)), -1)
        if end_i < 0:
            i += 1
            continue
        block = "\n".join(lines[i:end_i + 1])
        flat_block = re.sub(r"&\s*\n\s*&?\s*", " ", block)
        matrix_names: set[str] = set()
        declared: set[str] = set()
        for dm in re.finditer(
            r"(?im)^\s*(?:real\s*\([^)]*\)|integer|logical|complex\s*\([^)]*\)|character\s*(?:\([^)]*\))?|type\s*\([^)]*\))[^:]*::\s*(.+)$",
            flat_block,
        ):
            for item in split_top_level_commas(dm.group(1)):
                nm_m = re.match(r"\s*([A-Za-z]\w*)", item)
                if nm_m is not None:
                    declared.add(nm_m.group(1).lower())
                if re.search(r"\(:\s*,\s*:\)", item):
                    if nm_m is not None:
                        matrix_names.add(nm_m.group(1))
        first_exec = end_i
        for j in range(i + 1, end_i):
            ln = lines[j]
            if "::" in ln:
                for item in split_top_level_commas(ln.split("::", 1)[1]):
                    nm_m = re.match(r"\s*([A-Za-z]\w*)", item)
                    if nm_m is not None:
                        declared.add(nm_m.group(1).lower())
                    if re.search(r"\(:\s*,\s*:\)", item):
                        if nm_m is not None:
                            matrix_names.add(nm_m.group(1))
                continue
            if ln.lstrip().startswith("&"):
                continue
            if re.match(r"^\s*(?:use\b|implicit\s+none\b|public\b|private\b|contains\b|interface\b|end\s+interface\b|module\s+procedure\b|!)", ln, re.IGNORECASE):
                continue
            if ln.strip() == "":
                continue
            first_exec = j
            break
        missing: list[str] = []
        matrix_l = {nm.lower() for nm in matrix_names}
        for am in re.finditer(r"(?im)^\s*([A-Za-z]\w*)\s*=\s*([A-Za-z]\w*)\s*$", block):
            lhs = am.group(1)
            rhs = am.group(2)
            if lhs.lower() not in declared and rhs.lower() in matrix_l:
                missing.append(lhs)
                declared.add(lhs.lower())
        if missing:
            out.insert(first_exec + offset, "real(kind=dp), allocatable :: " + ", ".join(f"{nm}(:,:)" for nm in missing))
            offset += 1
        i = end_i + 1
    return "\n".join(out) + ("\n" if f90.endswith("\n") else "")


def remove_program_decls_for_public_module_vars_text(f90: str) -> str:
    """Remove program declarations that duplicate public module variables."""
    lines = f90.splitlines()
    module_vars_by_mod: dict[str, set[str]] = {}
    i = 0
    while i < len(lines):
        mm = re.match(r"^\s*module\s+([A-Za-z]\w*)\s*$", lines[i], re.IGNORECASE)
        if mm is None:
            i += 1
            continue
        mod_name = mm.group(1)
        end_i = next((j for j in range(i + 1, len(lines)) if re.match(r"^\s*end\s+module\b", lines[j], re.IGNORECASE)), -1)
        contains_i = next((j for j in range(i + 1, end_i if end_i >= 0 else len(lines)) if re.match(r"^\s*contains\s*$", lines[j], re.IGNORECASE)), -1)
        if end_i < 0 or contains_i < 0:
            i += 1
            continue
        header = "\n".join(lines[i + 1 : contains_i])
        public_names: set[str] = set()
        flat_header = re.sub(r"&\s*\n\s*&?\s*", " ", header)
        for pm in re.finditer(r"(?im)^\s*public\s*::\s*(.+)$", flat_header):
            for part in split_top_level_commas(pm.group(1)):
                nm = part.strip()
                if re.match(r"^[A-Za-z]\w*$", nm):
                    public_names.add(nm.lower())
        header_top_level = re.sub(
            r"(?ims)^\s*type(?:\s*,[^:]*)?\s*::\s*[A-Za-z]\w*\b.*?^\s*end\s+type\b[^\n]*",
            "",
            header,
        )
        flat_top = re.sub(r"&\s*\n\s*&?\s*", " ", header_top_level)
        module_vars: set[str] = set()
        for dm in re.finditer(
            r"(?im)^\s*(?:real\s*\([^)]*\)|integer|logical|complex\s*\([^)]*\)|character\s*(?:\([^)]*\))?)(?:\s*,\s*[^:]*)?::\s*(.+)$",
            flat_top,
        ):
            if re.search(r"\bparameter\b", dm.group(0), re.IGNORECASE):
                continue
            for part in split_top_level_commas(dm.group(1)):
                nm_m = re.match(r"\s*([A-Za-z]\w*)\b", part)
                if nm_m is not None and nm_m.group(1).lower() in public_names:
                    module_vars.add(nm_m.group(1).lower())
        if module_vars:
            module_vars_by_mod[mod_name.lower()] = module_vars
        i = end_i + 1
    if not module_vars_by_mod:
        return f90

    prog_i = next((j for j, ln in enumerate(lines) if re.match(r"^\s*program\b", ln, re.IGNORECASE)), -1)
    if prog_i < 0:
        return f90
    visible_vars: set[str] = set()
    for ln in lines[prog_i:]:
        um = re.match(r"^\s*use\s+([A-Za-z]\w*)\s*(?:,\s*only\s*:\s*(.*))?$", ln, re.IGNORECASE)
        if um is None:
            continue
        mod_vars = module_vars_by_mod.get(um.group(1).lower(), set())
        if not mod_vars:
            continue
        only = (um.group(2) or "").strip()
        if only:
            only_names = {p.split("=>", 1)[-1].strip().lower() for p in split_top_level_commas(only)}
            visible_vars.update(mod_vars & only_names)
        else:
            visible_vars.update(mod_vars)
    if not visible_vars:
        return f90

    out: list[str] = []
    for j, ln in enumerate(lines):
        if j < prog_i:
            out.append(ln)
            continue
        m_decl = re.match(
            r"^(\s*)((?:real|complex)\s*\(\s*kind\s*=\s*dp\s*\)|integer|logical|character\s*\([^)]*\))(\s*,\s*[^:]*)?::\s*(.+)$",
            ln,
            re.IGNORECASE,
        )
        if m_decl is None:
            out.append(ln)
            continue
        kept: list[str] = []
        parts = split_top_level_commas(m_decl.group(4))
        for part in parts:
            base = re.sub(r"\s*\(.*\)\s*$", "", part.split("=", 1)[0].strip()).strip()
            if base.lower() not in visible_vars:
                kept.append(part.strip())
        if not kept:
            continue
        if len(kept) != len(parts):
            out.append(f"{m_decl.group(1)}{m_decl.group(2)}{m_decl.group(3) or ''}:: {', '.join(kept)}")
        else:
            out.append(ln)
    return "\n".join(out) + ("\n" if f90.endswith("\n") else "")


def _r_mod_needed_public_names(f90: str) -> set[str]:
    txt = re.sub(r"&\s*\n\s*&?", "", f90)
    out: set[str] = set()
    for m in re.finditer(r"^\s*use\s+r_mod\s*,\s*only\s*:\s*(.+)$", txt, re.IGNORECASE | re.MULTILINE):
        for part in m.group(1).split(","):
            nm = part.strip()
            if "=>" in nm:
                nm = nm.split("=>", 1)[1].strip()
            if nm:
                out.add(nm)
    return out


def _render_r_mod_only(names: set[str]) -> str:
    rendered: list[str] = []
    for nm in sorted(names):
        if nm == "r_sd":
            rendered.append("r_sd => sd")
        elif nm == "print_matrix_rstyle":
            rendered.append("print_matrix => print_matrix_rstyle")
        else:
            rendered.append(nm)
    return ", ".join(rendered)


def _extract_r_mod(txt: str) -> str | None:
    m0 = re.search(r"^\s*module\s+r_mod\b", txt, re.IGNORECASE | re.MULTILINE)
    if m0 is None:
        return None
    m1 = re.search(r"^\s*end\s+module\s+r_mod\b.*$", txt[m0.start():], re.IGNORECASE | re.MULTILINE)
    if m1 is None:
        return txt[m0.start():]
    return txt[m0.start():m0.start() + m1.end()]


def _parse_r_mod_runtime(module_txt: str) -> tuple[list[str], dict[str, list[str]], dict[str, list[str]], dict[str, list[str]]]:
    lines = module_txt.splitlines()
    contains_idx = next((i for i, ln in enumerate(lines) if re.match(r"^\s*contains\s*$", ln, re.IGNORECASE)), -1)
    if contains_idx < 0:
        return lines, {}, {}, {}
    header = lines[:contains_idx]
    body = lines[contains_idx + 1:]

    interfaces: dict[str, list[str]] = {}
    procedures: dict[str, list[str]] = {}
    types: dict[str, list[str]] = {}
    header_out: list[str] = []
    i = 0
    while i < len(header):
        ln = header[i]
        m_int = re.match(r"^\s*interface\s+([A-Za-z]\w*)\b", ln, re.IGNORECASE)
        if m_int:
            name = m_int.group(1)
            block = [ln]
            i += 1
            while i < len(header):
                block.append(header[i])
                if re.match(r"^\s*end\s+interface\b", header[i], re.IGNORECASE):
                    i += 1
                    break
                i += 1
            interfaces[name.lower()] = block
            continue
        m_type = re.match(r"^\s*type\s*::\s*([A-Za-z]\w*)\b", ln, re.IGNORECASE)
        if m_type:
            name = m_type.group(1)
            block = [ln]
            i += 1
            while i < len(header):
                block.append(header[i])
                if re.match(r"^\s*end\s+type\b", header[i], re.IGNORECASE):
                    i += 1
                    break
                i += 1
            types[name.lower()] = block
            continue
        if re.match(r"^\s*public\b", ln, re.IGNORECASE):
            i += 1
            while i < len(header) and header[i - 1].rstrip().endswith("&"):
                i += 1
            continue
        header_out.append(ln)
        i += 1

    proc_start = re.compile(
        r"^\s*(?!end\b)(?:(?:pure|elemental|recursive|integer|logical|real(?:\([^)]*\))?|character(?:\([^)]*\))?|type\([^)]*\))\s+)*"
        r"(function|subroutine)\s+([A-Za-z]\w*)\b",
        re.IGNORECASE,
    )
    proc_end = re.compile(r"^\s*end\s+(function|subroutine)\b", re.IGNORECASE)
    i = 0
    while i < len(body):
        m = proc_start.match(body[i])
        if not m:
            i += 1
            continue
        name = m.group(2)
        block = [body[i]]
        i += 1
        while i < len(body):
            block.append(body[i])
            if proc_end.match(body[i]):
                i += 1
                break
            i += 1
        procedures[name.lower()] = block
    return header_out, interfaces, types, procedures


def _interface_procedures(block: list[str]) -> set[str]:
    out: set[str] = set()
    for ln in block:
        m = re.match(r"^\s*module\s+procedure\s+(.+)$", ln, re.IGNORECASE)
        if not m:
            continue
        for part in m.group(1).split(","):
            nm = part.strip().rstrip("&").strip()
            if nm:
                out.add(nm.lower())
    return out


def _declared_names_in_fortran_line(line: str) -> set[str]:
    code = fscan.strip_comment(line).strip()
    if "::" not in code:
        return set()
    lhs, rhs = code.split("::", 1)
    if re.match(r"^\s*(public|private|use|interface|module\s+procedure)\b", lhs, re.IGNORECASE):
        return set()
    out: set[str] = set()
    for part in split_top_level_commas(rhs):
        item = part.strip()
        if not item:
            continue
        item = item.split("=", 1)[0].strip()
        m = re.match(r"^([A-Za-z]\w*)", item)
        if m:
            out.add(m.group(1).lower())
    return out


def prune_r_mod_runtime(module_txt: str, public_needed: set[str]) -> str:
    header, interfaces, types, procedures = _parse_r_mod_runtime(module_txt)
    proc_names = set(procedures)
    iface_members = {name: _interface_procedures(block) for name, block in interfaces.items()}
    needed_public_l = {n.lower() for n in public_needed}
    keep_procs: set[str] = set()
    keep_ifaces: set[str] = set()

    def add_name(name_l: str) -> None:
        if name_l in interfaces:
            keep_ifaces.add(name_l)
            keep_procs.update(iface_members.get(name_l, set()))
        elif name_l in procedures:
            keep_procs.add(name_l)

    for nm in needed_public_l:
        add_name(nm)

    changed = True
    while changed:
        changed = False
        scan = "\n".join("\n".join(procedures[p]) for p in sorted(keep_procs) if p in procedures)
        for pname in sorted(proc_names - keep_procs):
            if re.search(rf"\b{re.escape(pname)}\s*\(", scan, re.IGNORECASE):
                keep_procs.add(pname)
                changed = True
        for iname, members in interfaces.items():
            if iname in keep_ifaces:
                continue
            if re.search(rf"\b{re.escape(iname)}\s*\(", scan, re.IGNORECASE):
                keep_ifaces.add(iname)
                before = len(keep_procs)
                keep_procs.update(members)
                changed = changed or len(keep_procs) != before

    kept_text = "\n".join("\n".join(procedures[p]) for p in sorted(keep_procs) if p in procedures)
    keep_types = {n for n in types if n in needed_public_l or re.search(rf"\btype\s*\(\s*{re.escape(n)}\s*\)", kept_text, re.IGNORECASE)}
    public_out = {n for n in public_needed if n.lower() in keep_ifaces or n.lower() in keep_procs or n.lower() in keep_types}
    used_header_names = {
        nm.lower()
        for nm in re.findall(r"\b[A-Za-z]\w*\b", kept_text + "\n" + "\n".join("\n".join(types[t]) for t in keep_types))
    }

    out: list[str] = []
    i_head = 0
    while i_head < len(header):
        ln = header[i_head]
        m_iso = re.match(r"^(\s*use\s*,\s*intrinsic\s*::\s*iso_fortran_env\s*,\s*only\s*:\s*)(.*)$", ln, re.IGNORECASE)
        if m_iso:
            imports = ["real64"]
            if "int64" in used_header_names:
                imports.append("int64")
            out.append(m_iso.group(1) + ", ".join(imports))
            i_head += 1
            continue
        m_ieee = re.match(r"^(\s*use\s*,\s*intrinsic\s*::\s*ieee_arithmetic\s*,\s*only\s*:\s*)(.*)$", ln, re.IGNORECASE)
        if m_ieee:
            block = [ln]
            i_head += 1
            while block[-1].rstrip().endswith("&") and i_head < len(header):
                block.append(header[i_head])
                i_head += 1
            imports_txt = " ".join(block)
            imports_txt = imports_txt.replace("&", " ")
            imports = []
            m_only = re.search(r"\bonly\s*:\s*(.*)$", imports_txt, re.IGNORECASE)
            if m_only:
                for part in m_only.group(1).split(","):
                    nm = part.strip()
                    if nm and nm.lower() in used_header_names:
                        imports.append(nm)
            if imports:
                out.append(m_ieee.group(1) + ", ".join(imports))
            continue
        names = _declared_names_in_fortran_line(ln)
        if names and "dp" not in names and not (names & used_header_names):
            i_head += 1
            continue
        out.append(ln)
        i_head += 1
    # Keep all simple module state declarations; procedures may depend on them.
    out.extend(_wrapped_public_line(public_out))
    for t in sorted(keep_types):
        out.append("")
        out.extend(types[t])
    for iface in sorted(keep_ifaces):
        out.append("")
        block = interfaces[iface]
        members = iface_members.get(iface, set()) & keep_procs
        if members:
            new_block: list[str] = [block[0]]
            emitted_members = False
            for ln in block[1:]:
                if re.match(r"^\s*module\s+procedure\b", ln, re.IGNORECASE):
                    if not emitted_members:
                        for pln in _wrapped_public_line(members):
                            new_block.append(pln.replace("public ::", "   module procedure"))
                        emitted_members = True
                elif re.match(r"^\s*end\s+interface\b", ln, re.IGNORECASE):
                    new_block.append(ln)
            out.extend(new_block)
        else:
            out.extend(block)
    out.append("")
    out.append("contains")
    for p in sorted(keep_procs):
        out.append("")
        out.extend(procedures[p])
    out.append("")
    out.append("end module r_mod")
    return "\n".join(normalize_fortran_lines(out, max_consecutive_blank=1)) + "\n"


def prepend_self_contained_runtime(f90: str, helper_paths: list[Path]) -> str:
    """Prepend a pruned r_mod runtime source so the emitted file can compile alone."""
    needed = _r_mod_needed_public_names(f90)
    runtime_parts: list[str] = []
    for hp in helper_paths:
        try:
            txt = hp.read_text(encoding="utf-8")
        except Exception:
            txt = hp.read_text(encoding="utf-8", errors="replace")
        mod_txt = _extract_r_mod(txt)
        if mod_txt is not None:
            runtime_parts.append(prune_r_mod_runtime(mod_txt, needed).rstrip())
    if not runtime_parts:
        return f90
    return "\n\n".join(runtime_parts) + "\n\n" + f90


@dataclass
class ListReturnSpec:
    fn_name: str
    root_fields: dict[str, object]
    nested_types: dict[tuple[str, ...], dict[str, object]]


def _split_top_level_else(text: str) -> tuple[str, str] | None:
    """Split `A else B` at top level, outside strings/parentheses."""
    in_single = False
    in_double = False
    esc = False
    depth = 0
    bdepth = 0
    i = 0
    while i < len(text):
        ch = text[i]
        if esc:
            esc = False
            i += 1
            continue
        if ch == "\\":
            esc = True
            i += 1
            continue
        if ch == "'" and not in_double:
            in_single = not in_single
            i += 1
            continue
        if ch == '"' and not in_single:
            in_double = not in_double
            i += 1
            continue
        if not in_single and not in_double:
            if ch == "(":
                depth += 1
            elif ch == ")" and depth > 0:
                depth -= 1
            elif depth == 0 and text[i : i + 5] == " else":
                left = text[:i].strip()
                right = text[i + 5 :].strip()
                if left and right:
                    return left, right
        i += 1
    return None


def _split_trailing_r_subset(expr: str) -> tuple[str, str] | None:
    s = expr.strip()
    if not s.endswith("]"):
        return None
    depth = 0
    par = 0
    brace = 0
    in_single = False
    in_double = False
    esc = False
    for i in range(len(s) - 1, -1, -1):
        ch = s[i]
        if esc:
            esc = False
            continue
        if ch == "\\":
            esc = True
            continue
        if ch == "'" and not in_double:
            in_single = not in_single
            continue
        if ch == '"' and not in_single:
            in_double = not in_double
            continue
        if in_single or in_double:
            continue
        if ch == "]":
            depth += 1
        elif ch == "[":
            depth -= 1
            if depth == 0 and par == 0 and brace == 0:
                return s[:i].strip(), s[i + 1 : -1].strip()
        elif ch == ")":
            par += 1
        elif ch == "(":
            par -= 1
        elif ch == "}":
            brace += 1
        elif ch == "{":
            brace -= 1
    return None


def _looks_vector_expr_for_recycle(expr: str) -> bool:
    t = fscan.strip_redundant_outer_parens_expr(expr.strip())
    if not t:
        return False
    if re.match(r"^[A-Za-z]\w*$", t) and t.lower() in _KNOWN_MATRIX_NAMES:
        return False
    if t.startswith("[") and t.endswith("]"):
        return True
    if _split_top_level_colon(t) is not None:
        return True
    if re.match(r"^[A-Za-z]\w*$", t) and t.lower() in _KNOWN_VECTOR_NAMES:
        return True
    c = parse_call_text(t)
    if c is None:
        return False
    nm = c[0].lower()
    return nm in {
        "c",
        "r_seq_int",
        "r_seq_len",
        "int_to_string",
        "real_to_string_f",
        "real_to_string_g",
        "r_seq_int_by",
        "r_seq_int_length",
        "r_seq_real_by",
        "r_seq_real_length",
        "r_rep_real",
        "r_rep_int",
        "r_rep_char",
        "runif_vec",
        "rnorm_vec",
        "numeric",
        "pack",
        "tail",
        "quantile",
        "r_add",
        "r_sub",
        "r_mul",
        "r_div",
    }


def _looks_matrix_expr(expr: str) -> bool:
    t = fscan.strip_redundant_outer_parens_expr(expr.strip())
    if re.match(r"^[A-Za-z]\w*$", t) and t.lower() in _KNOWN_MATRIX_NAMES:
        return True
    for tok in ("+", "-", "*", "/"):
        split = _split_top_level_token(t, tok, from_right=True)
        if split is not None:
            lhs, rhs = split
            if lhs.strip() and rhs.strip() and (_looks_matrix_expr(lhs) or _looks_matrix_expr(rhs)):
                return True
    c = parse_call_text(t)
    if c is None:
        return False
    if c[0].lower() in {
        "matrix",
        "array",
        "r_matmul",
        "crossprod",
        "tcrossprod",
        "t",
        "chol",
        "scale",
        "cor",
        "cov",
        "cov2cor",
    }:
        return True
    if c[0].lower() in {"forwardsolve", "backsolve"}:
        rhs_src = c[1][1].strip() if len(c[1]) >= 2 else c[2].get("b", c[2].get("x", "")).strip()
        return _looks_matrix_expr(rhs_src) if rhs_src else False
    if c[0].lower() == "reshape":
        shape_src = ""
        if len(c[1]) >= 2:
            shape_src = c[1][1].strip()
        elif "shape" in c[2]:
            shape_src = c[2]["shape"].strip()
        if _parse_matrix_dim2(shape_src) is not None:
            return True
        return shape_src.startswith("[") and shape_src.endswith("]") and len(split_top_level_commas(shape_src[1:-1])) >= 2
    return False


def _parse_if_head(line: str) -> tuple[str, str] | None:
    s = line.strip()
    if not s.startswith("if"):
        return None
    m = re.match(r"^if\s*\(", s)
    if not m:
        return None
    i = m.end() - 1
    depth = 0
    bdepth = 0
    in_single = False
    in_double = False
    esc = False
    j = i
    while j < len(s):
        ch = s[j]
        if esc:
            esc = False
            j += 1
            continue
        if ch == "\\":
            esc = True
            j += 1
            continue
        if ch == "'" and not in_double:
            in_single = not in_single
            j += 1
            continue
        if ch == '"' and not in_single:
            in_double = not in_double
            j += 1
            continue
        if not in_single and not in_double:
            if ch == "(":
                depth += 1
            elif ch == ")":
                depth -= 1
                if depth == 0:
                    return s[i + 1 : j].strip(), s[j + 1 :].strip()
        j += 1
    return None


def _parse_while_head(line: str) -> tuple[str, str] | None:
    s = line.strip()
    if not s.startswith("while"):
        return None
    m = re.match(r"^while\s*\(", s)
    if not m:
        return None
    i = m.end() - 1
    depth = 0
    bdepth = 0
    in_single = False
    in_double = False
    esc = False
    j = i
    while j < len(s):
        ch = s[j]
        if esc:
            esc = False
            j += 1
            continue
        if ch == "\\":
            esc = True
            j += 1
            continue
        if ch == "'" and not in_double:
            in_single = not in_single
            j += 1
            continue
        if ch == '"' and not in_single:
            in_double = not in_double
            j += 1
            continue
        if not in_single and not in_double:
            if ch == "(":
                depth += 1
            elif ch == ")":
                depth -= 1
                if depth == 0:
                    return s[i + 1 : j].strip(), s[j + 1 :].strip()
        j += 1
    return None


def _custom_infix_function_name(op: str) -> str:
    inner = op.strip()
    if inner.startswith("%") and inner.endswith("%") and len(inner) >= 2:
        inner = inner[1:-1]
    base = _fortran_ident(inner)
    if not base:
        base = "op"
    return base if base.startswith("op_") else f"op_{base}"


def _parse_function_assign_head(line: str) -> tuple[str, str, str] | None:
    s = line.strip()
    m_op = re.match(r"""^["'](%[^"']+%)["']\s*(?:<-|=)\s*function\s*\(""", s)
    if m_op:
        raw_op = m_op.group(1)
        fname = _custom_infix_function_name(raw_op)
        _CUSTOM_INFIX_OPS[raw_op] = fname
        _CUSTOM_INFIX_OPS[raw_op.lower()] = fname
        i = m_op.end() - 1
    else:
        m = re.match(r"^([A-Za-z]\w*(?:\.[A-Za-z]\w*)*)\s*(?:<-|=)\s*function\s*\(", s)
        if not m:
            return None
        fname = m.group(1)
        i = m.end() - 1
    depth = 0
    bdepth = 0
    in_single = False
    in_double = False
    esc = False
    j = i
    while j < len(s):
        ch = s[j]
        if esc:
            esc = False
            j += 1
            continue
        if ch == "\\":
            esc = True
            j += 1
            continue
        if ch == "'" and not in_double:
            in_single = not in_single
            j += 1
            continue
        if ch == '"' and not in_single:
            in_double = not in_double
            j += 1
            continue
        if not in_single and not in_double:
            if ch == "(":
                depth += 1
            elif ch == ")":
                depth -= 1
                if depth == 0:
                    return fname, s[i + 1 : j].strip(), s[j + 1 :].strip()
        j += 1
    return None


def _parse_for_head(line: str) -> tuple[str, str, str] | None:
    s = line.strip()
    if not s.startswith("for"):
        return None
    m = re.match(r"^for\s*\(", s)
    if not m:
        return None
    i0 = m.end() - 1
    depth = 0
    in_single = False
    in_double = False
    esc = False
    j = i0
    while j < len(s):
        ch = s[j]
        if esc:
            esc = False
            j += 1
            continue
        if ch == "\\":
            esc = True
            j += 1
            continue
        if ch == "'" and not in_double:
            in_single = not in_single
            j += 1
            continue
        if ch == '"' and not in_single:
            in_double = not in_double
            j += 1
            continue
        if not in_single and not in_double:
            if ch == "(":
                depth += 1
            elif ch == ")":
                depth -= 1
                if depth == 0:
                    inside = s[i0 + 1 : j].strip()
                    tail = s[j + 1 :].strip()
                    m_in = re.match(rf"^({_R_IDENT_RE})\s+in\s+(.+)$", inside)
                    if not m_in:
                        return None
                    raw_var = m_in.group(1)
                    var = _sanitize_r_var_name(raw_var)
                    if raw_var != var:
                        _DOTTED_VAR_RENAMES[raw_var] = var
                    return var, m_in.group(2).strip(), tail
        j += 1
    return None


def parse_call_text(txt: str) -> tuple[str, list[str], dict[str, str]] | None:
    s = txt.strip()
    m = re.match(r"^([A-Za-z]\w*(?:\.[A-Za-z]\w*)*)\s*\(", s)
    if not m:
        return None
    nm = m.group(1)
    open_i = s.find("(", m.end(1))
    depth = 0
    quote: str | None = None
    esc = False
    close_i = -1
    for i in range(open_i, len(s)):
        ch = s[i]
        if quote is not None:
            if esc:
                esc = False
            elif ch == "\\":
                esc = True
            elif ch == quote:
                quote = None
            continue
        if ch in {"'", '"'}:
            quote = ch
            continue
        if ch == "(":
            depth += 1
        elif ch == ")":
            depth -= 1
            if depth == 0:
                close_i = i
                break
    if close_i < 0 or s[close_i + 1 :].strip():
        return None
    inner = s[open_i + 1 : close_i].strip()
    parts = split_top_level_commas(inner) if inner else []
    pos: list[str] = []
    kw: dict[str, str] = {}
    for p in parts:
        pt = p.strip()
        if pt == "...":
            continue
        asn = split_top_level_assignment(pt)
        if asn is not None:
            lhs = asn[0].strip()
            rhs = asn[1].strip()
            if re.match(r"^[A-Za-z]\w*(?:\.[A-Za-z]\w*)*$", lhs):
                kw[lhs] = rhs
                continue
        pos.append(pt)
    return nm, pos, kw


def _trycatch_primary_expr(src: str) -> str | None:
    c = parse_call_text(src.strip())
    if c is None or c[0].lower() != "trycatch":
        return None
    if c[1]:
        return c[1][0].strip()
    expr = c[2].get("expr")
    return expr.strip() if expr else None


def _parse_quoted_operator_call(txt: str) -> tuple[str, list[str]] | None:
    s = txt.strip()
    if not s or s[0] not in {"'", '"', "`"}:
        return None
    q = s[0]
    end_q = s.find(q, 1)
    if end_q < 0:
        return None
    op = s[1:end_q]
    rest = s[end_q + 1 :].lstrip()
    if not rest.startswith("("):
        return None
    open_i = len(s) - len(rest)
    depth = 0
    quote: str | None = None
    esc = False
    close_i = -1
    for i in range(open_i, len(s)):
        ch = s[i]
        if quote is not None:
            if esc:
                esc = False
            elif ch == "\\":
                esc = True
            elif ch == quote:
                quote = None
            continue
        if ch in {"'", '"', "`"}:
            quote = ch
            continue
        if ch == "(":
            depth += 1
        elif ch == ")":
            depth -= 1
            if depth == 0:
                close_i = i
                break
    if close_i < 0 or s[close_i + 1 :].strip():
        return None
    inner = s[open_i + 1 : close_i].strip()
    args = split_top_level_commas(inner) if inner else []
    return op, args


def _strip_variadic_actuals_in_calls(expr: str) -> str:
    """Remove `...` arguments from function calls in R-like expression strings."""

    def _filter_parts(inner: str) -> str:
        parts = split_top_level_commas(inner) if inner.strip() else []
        kept: list[str] = []
        for p in parts:
            t = p.strip()
            if not t or t == "...":
                continue
            kept.append(t)
        return ", ".join(kept)

    def _scan(text: str) -> str:
        out: list[str] = []
        n = len(text)
        i = 0
        in_single = False
        in_double = False
        esc = False
        while i < n:
            ch = text[i]
            if esc:
                esc = False
                out.append(ch)
                i += 1
                continue
            if ch == "\\":
                esc = True
                out.append(ch)
                i += 1
                continue
            if in_single:
                if ch == "'" and not in_double:
                    in_single = False
                out.append(ch)
                i += 1
                continue
            if in_double:
                if ch == '"' and not in_single:
                    in_double = False
                out.append(ch)
                i += 1
                continue
            if ch == "'":
                in_single = True
                out.append(ch)
                i += 1
                continue
            if ch == '"':
                in_double = True
                out.append(ch)
                i += 1
                continue
            if ch.isalpha() or ch == "_":
                m_name = re.match(r"[A-Za-z]\w*(?:\.[A-Za-z]\w*)*", text[i:])
                if m_name is None:
                    out.append(ch)
                    i += 1
                    continue
                name = m_name.group(0)
                j = i + m_name.end()
                k = j
                while k < n and text[k].isspace():
                    k += 1
                if k >= n or text[k] != "(":
                    out.append(text[i:k])
                    i = k
                    continue
                depth = 0
                q: str | None = None
                esc2 = False
                p = k
                close = -1
                while p < n:
                    c2 = text[p]
                    if q is not None:
                        if esc2:
                            esc2 = False
                        elif c2 == "\\":
                            esc2 = True
                        elif c2 == q:
                            q = None
                        p += 1
                        continue
                    if c2 in {"'", '"'}:
                        q = c2
                    elif c2 == "\\":
                        esc2 = True
                    elif c2 == "(":
                        depth += 1
                    elif c2 == ")":
                        if depth == 1:
                            close = p
                            break
                        depth -= 1
                    p += 1
                if close < 0:
                    out.append(text[i: k + 1])
                    i = k + 1
                    continue
                inner = text[k + 1 : close]
                inner_clean = _scan(inner)
                out.append(name)
                out.append("(")
                out.append(_filter_parts(inner_clean))
                out.append(")")
                i = close + 1
            else:
                out.append(ch)
                i += 1
        return "".join(out)

    return _scan(expr)


def _sanitize_fortran_kwarg_name(name: str) -> str:
    """Map R-style keyword names to valid Fortran named-argument identifiers."""
    nm = name.strip()
    if not nm:
        return nm
    nm = nm.replace(".", "_")
    nm = re.sub(r"[^A-Za-z0-9_]", "_", nm)
    if nm and nm[0].isdigit():
        nm = "_" + nm
    return nm


def _shorten_fortran_identifier(name: str, max_len: int = _FORTRAN_MAX_IDENTIFIER_LEN) -> str:
    """Return a stable Fortran identifier no longer than the standard limit."""
    if len(name) <= max_len:
        return name
    if max_len <= 9:
        return name[:max_len]
    digest = hashlib.sha1(name.encode("utf-8", errors="replace")).hexdigest()[:8]
    stem_len = max_len - len(digest) - 1
    stem = name[:stem_len].rstrip("_") or name[:stem_len]
    return f"{stem}_{digest}"


def _integrate_closure_wrapper_name(helper_name: str, captures: list[str]) -> str:
    """Name a lifted integrate() closure while keeping wrapper captures legal."""
    wrapper_base = f"{helper_name}_xr2f_integrate_closure"
    wrapper_max = _FORTRAN_MAX_IDENTIFIER_LEN - len("_result")
    if len(wrapper_base) <= wrapper_max and all(
        len(f"{wrapper_base}_{cap}") <= _FORTRAN_MAX_IDENTIFIER_LEN for cap in captures
    ):
        return wrapper_base
    cap_room = 0 if not captures else 1 + max(len(cap) for cap in captures)
    return _shorten_fortran_identifier(
        f"{helper_name}_xric",
        max(1, min(wrapper_max, _FORTRAN_MAX_IDENTIFIER_LEN - cap_room)),
    )


def _sanitize_r_var_name(name: str) -> str:
    """Map an R variable name to a valid Fortran identifier without function-name collisions."""
    nm = name.strip()
    cached = _SANITIZED_R_NAME_BY_RAW.get(nm)
    if cached is not None:
        return cached
    raw_nm = nm
    leading_dot = nm.startswith(".")
    if leading_dot:
        leading = len(nm) - len(nm.lstrip("."))
        nm = ("dot_" * leading) + nm[leading:]
    if "." in nm:
        nm = nm.replace(".", "_dot_")
    nm = re.sub(r"[^A-Za-z0-9_]", "_", nm)
    if nm and nm[0].isdigit():
        nm = "_" + nm
    if leading_dot:
        base = nm or "dot"
        cand = base
        i = 2
        while cand != raw_nm and cand in _RAW_R_IDENT_NAMES:
            cand = f"{base}_{i}"
            i += 1
        nm = cand
    _SANITIZED_R_NAME_BY_RAW[raw_nm] = nm
    return nm


def _collect_raw_r_ident_names(src: str) -> set[str]:
    out: set[str] = set()
    pat = re.compile(_R_IDENT_RE)
    for raw in src.splitlines():
        code, _cmt = split_r_code_comment(raw)
        for m in pat.finditer(code):
            start, end = m.span()
            if start > 0 and re.match(r"[A-Za-z0-9_.]", code[start - 1]):
                continue
            if end < len(code) and re.match(r"[A-Za-z0-9_.]", code[end]):
                continue
            out.add(m.group(0))
    return out


def _replace_dotted_var_refs(expr: str) -> str:
    out = expr
    for src, dst in sorted(_DOTTED_VAR_RENAMES.items(), key=lambda kv: len(kv[0]), reverse=True):
        pat = re.compile(
            rf"(?<![A-Za-z0-9_.]){re.escape(src)}(?![A-Za-z0-9_.])(?!(?:\s*\())"
        )
        out = pat.sub(dst, out)
    return out


def _looks_vector_actual_for_matrix_arg(src: str, lowered: str) -> bool:
    """Heuristic for wrapping a vector actual when a helper expects a matrix."""
    t = lowered.strip()
    if re.match(r"^[A-Za-z]\w*(?:%[A-Za-z]\w*)?\(:,\s*[^,()]+\)$", t):
        return True
    if re.match(r"^[A-Za-z]\w*(?:%[A-Za-z]\w*)?\([^,()]+:\s*[^,()]+\)$", t):
        return True
    s = src.strip()
    if re.match(r"^[A-Za-z]\w*(?:\$[A-Za-z]\w*)?\s*\[\[\s*.+\s*\]\]$", s):
        return True
    return False


def _fortran_str_literal(raw: str) -> str:
    txt = raw.replace('"', '""')
    return f'"{txt}"'


def _dequote_string_literal(s: str) -> str | None:
    t = s.strip()
    if len(t) >= 2 and ((t[0] == '"' and t[-1] == '"') or (t[0] == "'" and t[-1] == "'")):
        return t[1:-1]
    return None


def _strip_named_actual_value(txt: str) -> str:
    """Return the value side for simple R named actuals such as `a = 10`."""
    asn = split_top_level_assignment(txt.strip())
    if asn is None:
        return txt.strip()
    lhs, rhs = asn[0].strip(), asn[1].strip()
    if re.match(r"^[A-Za-z]\w*(?:\.[A-Za-z]\w*)*$", lhs):
        return rhs
    return txt.strip()


def _parse_named_c_vector(expr: str) -> tuple[list[str], list[str]] | None:
    cinfo = parse_call_text(expr.strip())
    if cinfo is None or cinfo[0].lower() != "c":
        return None
    _nm, pos, kw = cinfo
    if not pos and not kw:
        return None
    labels: list[str] = []
    values: list[str] = []
    for raw in pos:
        asn = split_top_level_assignment(raw.strip())
        if asn is None:
            return None
        lab, val = asn[0].strip(), asn[1].strip()
        if not re.match(r"^[A-Za-z]\w*(?:\.[A-Za-z]\w*)*$", lab):
            return None
        labels.append(lab)
        values.append(val)
    for lab, val in kw.items():
        if not re.match(r"^[A-Za-z]\w*(?:\.[A-Za-z]\w*)*$", lab):
            return None
        labels.append(lab)
        values.append(val.strip())
    return labels, values


def _parse_string_c_vector(expr: str) -> list[str] | None:
    cinfo = parse_call_text(expr.strip())
    if cinfo is None or cinfo[0].lower() != "c":
        return None
    vals = cinfo[1] + list(cinfo[2].values())
    labels: list[str] = []
    for v in vals:
        lab = _dequote_string_literal(v.strip())
        if lab is None:
            return None
        labels.append(lab)
    return labels


def collect_named_c_labels(stmts: list[object]) -> dict[str, list[str]]:
    labels_by_name: dict[str, list[str]] = {}
    conflicted: set[str] = set()
    function_returns: dict[str, list[str]] = {}

    def expr_labels(expr: str) -> list[str] | None:
        parsed = _parse_named_c_vector(expr.strip())
        if parsed is not None:
            return parsed[0]
        c_ret = parse_call_text(expr.strip())
        if c_ret is not None and c_ret[0].lower() == "return" and c_ret[1]:
            parsed_ret = _parse_named_c_vector(c_ret[1][0].strip())
            if parsed_ret is not None:
                return parsed_ret[0]
        return None

    def collect_function_returns(items: list[object]) -> None:
        for st in items:
            if isinstance(st, FuncDef):
                local_labels: dict[str, list[str]] = {}
                changed_local_labels = True
                while changed_local_labels:
                    changed_local_labels = False
                    for inner_assign in st.body:
                        if not isinstance(inner_assign, Assign):
                            continue
                        lhs_l = inner_assign.name.lower()
                        if lhs_l in local_labels:
                            continue
                        parsed_assign = _parse_named_c_vector(inner_assign.expr.strip())
                        if parsed_assign is not None:
                            local_labels[lhs_l] = parsed_assign[0]
                            changed_local_labels = True
                            continue
                        rhs_s = inner_assign.expr.strip()
                        if re.fullmatch(r"[A-Za-z]\w*", rhs_s):
                            rhs_labels = local_labels.get(rhs_s.lower())
                            if rhs_labels is not None:
                                local_labels[lhs_l] = list(rhs_labels)
                                changed_local_labels = True
                for inner in reversed(st.body):
                    if isinstance(inner, ExprStmt):
                        labs = expr_labels(inner.expr)
                        if labs is None:
                            t_inner = inner.expr.strip()
                            c_inner = parse_call_text(t_inner)
                            if c_inner is not None and c_inner[0].lower() == "return" and c_inner[1]:
                                t_inner = c_inner[1][0].strip()
                            if re.fullmatch(r"[A-Za-z]\w*", t_inner):
                                labs = local_labels.get(t_inner.lower())
                        if labs is not None:
                            function_returns[st.name.lower()] = labs
                        break
                    if isinstance(inner, Assign):
                        break
                    if isinstance(inner, CommentStmt):
                        continue
                collect_function_returns(st.body)
            elif isinstance(st, IfStmt):
                collect_function_returns(st.then_body)
                collect_function_returns(st.else_body)
            elif isinstance(st, ForStmt):
                collect_function_returns(st.body)
            elif isinstance(st, WhileStmt):
                collect_function_returns(st.body)
            elif isinstance(st, RepeatStmt):
                collect_function_returns(st.body)

    def add(name: str, labels: list[str]) -> None:
        key = name.lower()
        if key in conflicted:
            return
        prev = labels_by_name.get(key)
        if prev is None:
            labels_by_name[key] = list(labels)
        elif prev != labels:
            labels_by_name.pop(key, None)
            conflicted.add(key)

    def walk(items: list[object]) -> None:
        for st in items:
            if isinstance(st, Assign):
                labs = expr_labels(st.expr.strip())
                if labs is None:
                    c_assign = parse_call_text(st.expr.strip())
                    if c_assign is not None:
                        labs = function_returns.get(c_assign[0].lower())
                if labs is not None:
                    add(st.name, labs)
            elif isinstance(st, FuncDef):
                walk(st.body)
            elif isinstance(st, IfStmt):
                walk(st.then_body)
                walk(st.else_body)
            elif isinstance(st, ForStmt):
                walk(st.body)
            elif isinstance(st, WhileStmt):
                walk(st.body)
            elif isinstance(st, RepeatStmt):
                walk(st.body)

    collect_function_returns(stmts)
    walk(stmts)
    return labels_by_name


def _array_dim_parts(expr: str) -> list[str] | None:
    cinfo = parse_call_text(expr.strip())
    if cinfo is None or cinfo[0].lower() != "array":
        return None
    _nm, pos, kw = cinfo
    dim_src = kw.get("dim")
    if dim_src is None and len(pos) >= 2:
        dim_src = pos[1]
    if dim_src is None:
        return None
    dim_txt = dim_src.strip()
    cdim = parse_call_text(dim_txt)
    if cdim is not None and cdim[0].lower() == "c":
        return [p.strip() for p in cdim[1] + list(cdim[2].values()) if p.strip()]
    if dim_txt.startswith("[") and dim_txt.endswith("]"):
        return [p.strip() for p in split_top_level_commas(dim_txt[1:-1]) if p.strip()]
    return [dim_txt] if dim_txt else None


def _array_dim_omitted(expr: str) -> bool:
    cinfo = parse_call_text(expr.strip())
    if cinfo is None or cinfo[0].lower() != "array":
        return False
    _nm, pos, kw = cinfo
    return "dim" not in {k.lower(): v for k, v in kw.items()} and len(pos) < 2


def _parse_reduce_call(expr: str) -> tuple[str, str] | None:
    cinfo = parse_call_text(expr.strip())
    if cinfo is None or cinfo[0].lower() != "reduce":
        return None
    _nm, pos, kw = cinfo
    fn_src = pos[0].strip() if pos else kw.get("f", kw.get("FUN", "")).strip()
    x_src = pos[1].strip() if len(pos) >= 2 else kw.get("x", kw.get("init", "")).strip()
    if not fn_src or not x_src:
        return None
    return fn_src, x_src


def _reduce_vector_size_expr(vec_src: str) -> str:
    t = vec_src.strip()
    cinfo = parse_call_text(t)
    if cinfo is not None and cinfo[1]:
        nm = cinfo[0].lower()
        if nm in {"abs", "as.integer", "as.numeric", "as.double", "int", "real"}:
            return _reduce_vector_size_expr(cinfo[1][0].strip())
    return f"size({r_expr_to_fortran(t)})"


def _reduce_vector_element_expr(vec_src: str, idx_expr: str) -> str:
    t = vec_src.strip()
    cinfo = parse_call_text(t)
    if cinfo is not None and cinfo[1]:
        nm = cinfo[0].lower()
        inner = cinfo[1][0].strip()
        if nm == "abs":
            return f"abs({_reduce_vector_element_expr(inner, idx_expr)})"
        if nm in {"as.integer", "int"}:
            return f"int({_reduce_vector_element_expr(inner, idx_expr)})"
        if nm in {"as.numeric", "as.double", "real"}:
            return f"real({_reduce_vector_element_expr(inner, idx_expr)}, kind=dp)"
    if re.fullmatch(r"[A-Za-z]\w*", t):
        return f"{r_expr_to_fortran(t)}({idx_expr})"
    return f"{r_expr_to_fortran(t)}({idx_expr})"


def _reduce_step_expr(fn_src: str, acc_expr: str, item_expr: str) -> str:
    f = fn_src.strip()
    m_inline = re.match(
        r"^function\s*\(\s*([A-Za-z]\w*)\s*,\s*([A-Za-z]\w*)\s*\)\s*(.+)$",
        f,
        re.IGNORECASE | re.DOTALL,
    )
    if m_inline is not None:
        a_nm, b_nm, body_src = m_inline.group(1), m_inline.group(2), m_inline.group(3).strip()
        body_src = _replace_idents(body_src, {a_nm: acc_expr, b_nm: item_expr})
        return r_expr_to_fortran(body_src)
    return f"{r_expr_to_fortran(f)}({acc_expr}, {item_expr})"


def _warn_mixed_character_coercion(expr: str) -> None:
    key = " ".join(expr.strip().split())
    if key in _MIXED_CHARACTER_COERCION_WARNINGS:
        return
    _MIXED_CHARACTER_COERCION_WARNINGS.add(key)
    _emit_warning(
        f"Warning: R expression `{key}` mixes character and non-character values; "
        "translating by coercing all elements to character."
    )


def _collect_character0_assignments(stmts: list[object]) -> set[str]:
    out: set[str] = set()

    def walk(ss: list[object]) -> None:
        for st in ss:
            if isinstance(st, Assign):
                if re.match(r"^\s*character\s*\(\s*0\s*\)\s*$", st.expr.strip(), re.IGNORECASE):
                    out.add(st.name.lower())
            elif isinstance(st, IfStmt):
                walk(st.then_body)
                walk(st.else_body)
            elif isinstance(st, ForStmt):
                walk(st.body)
            elif isinstance(st, WhileStmt):
                walk(st.body)
            elif isinstance(st, RepeatStmt):
                walk(st.body)
            elif isinstance(st, SwitchStmt):
                for _label, body in st.cases:
                    walk(body)
                walk(st.default_body)

    walk(stmts)
    return out


def _array_data_is_integer(expr: str) -> bool:
    cinfo = parse_call_text(expr.strip())
    if cinfo is None or cinfo[0].lower() != "array":
        return False
    data_src = cinfo[1][0] if cinfo[1] else cinfo[2].get("data", "0")
    data_txt = data_src.strip()
    return (
        _is_int_literal(data_txt)
        or _split_top_level_colon(data_txt) is not None
        or data_txt.lower().startswith(("integer(", "raw(", "r_seq_int(", "r_seq_len(", "r_rep_int("))
    )


def _parse_array_dim_labels(expr: str) -> list[list[str]] | None:
    cinfo = parse_call_text(expr.strip())
    if cinfo is None or cinfo[0].lower() != "array":
        return None
    dimnames_src = cinfo[2].get("dimnames")
    if dimnames_src is None:
        return None
    linfo = parse_call_text(dimnames_src.strip())
    if linfo is None or linfo[0].lower() != "list":
        return None
    items = linfo[1] + list(linfo[2].values())
    labels: list[list[str]] = []
    for item in items:
        labs = _parse_string_c_vector(item.strip())
        if labs is None:
            return None
        labels.append(labs)
    return labels


def _parse_array_dim_label_sources(expr: str) -> list[str] | None:
    cinfo = parse_call_text(expr.strip())
    if cinfo is None or cinfo[0].lower() not in {"array", "matrix"}:
        return None
    dimnames_src = cinfo[2].get("dimnames")
    if dimnames_src is None:
        return None
    c_dimnames = parse_call_text(dimnames_src.strip())
    if c_dimnames is not None and c_dimnames[0].lower() == "dimnames":
        src = c_dimnames[1][0].strip() if c_dimnames[1] else c_dimnames[2].get("x", "").strip()
        if src:
            return [f"rownames({src})", f"colnames({src})"]
    linfo = parse_call_text(dimnames_src.strip())
    if linfo is None or linfo[0].lower() != "list":
        return None
    items = linfo[1] + list(linfo[2].values())
    return [item.strip() for item in items]


def _numeric_list_array_expr(expr: str) -> tuple[str, int] | None:
    """Lower simple numeric list(...) of equal vectors/matrices to rank-2/3 arrays."""
    cinfo = parse_call_text(expr.strip())
    if cinfo is None or cinfo[0].lower() != "list" or not cinfo[1]:
        return None
    items = [p.strip() for p in cinfo[1]]

    def _literal_vals(src: str) -> list[str] | None:
        t = r_expr_to_fortran(src).strip()
        if not (t.startswith("[") and t.endswith("]")):
            return None
        return [v.strip() for v in split_top_level_commas(t[1:-1]) if v.strip()]

    vec_vals = [_literal_vals(p) for p in items]
    if all(v is not None for v in vec_vals):
        vals2 = [v for v in vec_vals if v is not None]
        n = len(vals2[0])
        if n > 0 and all(len(v) == n for v in vals2):
            flat = ", ".join(x for v in vals2 for x in v)
            return f"reshape([{flat}], [{n}, {len(vals2)}])", 2

    mats: list[tuple[list[str], int, int, str, str, bool]] = []
    for p in items:
        cm = parse_call_text(p)
        if cm is None or cm[0].lower() != "matrix":
            mats = []
            break
        _nm, pos, kw = cm
        data_src = pos[0] if pos else kw.get("data")
        nr_src = kw.get("nrow") or (pos[1] if len(pos) >= 2 else None)
        nc_src = kw.get("ncol") or (pos[2] if len(pos) >= 3 else None)
        if data_src is None or nr_src is None:
            mats = []
            break
        vals = _literal_vals(data_src)
        if vals is None:
            mats = []
            break
        nr_f = _int_bound_expr(r_expr_to_fortran(nr_src))
        try:
            nr = int(nr_f)
        except ValueError:
            nr = int(round(len(vals) ** 0.5)) if nc_src is None and int(round(len(vals) ** 0.5)) ** 2 == len(vals) else 0
        if nc_src is not None:
            nc_f = _int_bound_expr(r_expr_to_fortran(nc_src))
            try:
                nc = int(nc_f)
            except ValueError:
                nc = len(vals) // nr if nr > 0 and len(vals) % nr == 0 else 0
        else:
            nc = len(vals) // nr if nr > 0 and len(vals) % nr == 0 else 0
            nc_f = str(nc) if nr_f.isdigit() else f"({len(vals)} / ({nr_f}))"
        if nr <= 0 or nc <= 0:
            mats = []
            break
        byrow_src = kw.get("byrow") or (pos[3] if len(pos) >= 4 else "")
        byrow = str(byrow_src).strip().upper() in {"TRUE", ".TRUE.", "T", "1"}
        if len(vals) != nr * nc:
            mats = []
            break
        mats.append((vals, nr, nc, nr_f, nc_f, byrow))
    if mats:
        nr0, nc0, nr0_f, nc0_f = mats[0][1], mats[0][2], mats[0][3], mats[0][4]
        if all(nr == nr0 and nc == nc0 and nr_f == nr0_f and nc_f == nc0_f for _vals, nr, nc, nr_f, nc_f, _byrow in mats):
            flat_parts: list[str] = []
            for vals, nr, nc, _nr_f, _nc_f, byrow in mats:
                if byrow:
                    flat_parts.extend(vals[r * nc + c] for c in range(nc) for r in range(nr))
                else:
                    flat_parts.extend(vals)
            return f"reshape([{', '.join(flat_parts)}], [{nr0_f}, {nc0_f}, {len(mats)}])", 3
    return None


def _numeric_nested_matrix_list_array_expr(expr: str) -> tuple[str, int] | None:
    cinfo = parse_call_text(expr.strip())
    if cinfo is None or cinfo[0].lower() != "list" or not cinfo[1]:
        return None
    regimes: list[list[tuple[list[str], int, int, bool]]] = []

    def _literal_vals(src: str) -> list[str] | None:
        t = r_expr_to_fortran(src).strip()
        if not (t.startswith("[") and t.endswith("]")):
            return None
        return [v.strip() for v in split_top_level_commas(t[1:-1]) if v.strip()]

    for item in cinfo[1]:
        inner = parse_call_text(item.strip())
        if inner is None or inner[0].lower() != "list" or not inner[1]:
            return None
        mats: list[tuple[list[str], int, int, bool]] = []
        for p in inner[1]:
            cm = parse_call_text(p.strip())
            if cm is None or cm[0].lower() != "matrix":
                return None
            _nm, pos, kw = cm
            data_src = pos[0] if pos else kw.get("data")
            nr_src = kw.get("nrow") or (pos[1] if len(pos) >= 2 else None)
            nc_src = kw.get("ncol") or (pos[2] if len(pos) >= 3 else None)
            if data_src is None or nr_src is None:
                return None
            vals = _literal_vals(data_src)
            if vals is None:
                return None
            nr = int(_int_bound_expr(r_expr_to_fortran(nr_src)))
            nc = int(_int_bound_expr(r_expr_to_fortran(nc_src))) if nc_src is not None else len(vals) // nr
            byrow_src = kw.get("byrow") or (pos[3] if len(pos) >= 4 else "")
            byrow = str(byrow_src).strip().upper() in {"TRUE", ".TRUE.", "T", "1"}
            if len(vals) != nr * nc:
                return None
            mats.append((vals, nr, nc, byrow))
        regimes.append(mats)
    nr0, nc0 = regimes[0][0][1], regimes[0][0][2]
    if any(nr != nr0 or nc != nc0 for mats in regimes for _vals, nr, nc, _byrow in mats):
        return None
    max_lag = max(len(mats) for mats in regimes)
    nan = "ieee_value(0.0_dp, ieee_quiet_nan)"
    flat_parts: list[str] = []
    for regime in regimes:
        for lag_i in range(max_lag):
            if lag_i >= len(regime):
                flat_parts.extend([nan] * (nr0 * nc0))
                continue
            vals, nr, nc, byrow = regime[lag_i]
            if byrow:
                flat_parts.extend(vals[r * nc + c] for c in range(nc) for r in range(nr))
            else:
                flat_parts.extend(vals)
    return f"reshape([{', '.join(flat_parts)}], [{nr0}, {nc0}, {max_lag}, {len(regimes)}])", 4


def _selects_named_order_column(expr: str) -> bool:
    m = re.match(r"^([A-Za-z]\w*)\s*\[(.*)\]$", expr.strip())
    if m is None:
        return False
    dims = _split_index_dims(m.group(2).strip())
    if len(dims) < 2:
        return False
    name_idx = _name_indices_from_subscript(m.group(1), dims[1].strip())
    labels = _NAMED_VECTOR_LABELS.get(m.group(1).lower())
    return name_idx == [1] and bool(labels) and labels[0].lower() == "order"


def _name_indices_from_subscript(base: str, inner: str) -> list[int] | None:
    labels = _NAMED_VECTOR_LABELS.get(base.lower())
    if not labels:
        return None
    t = inner.strip()
    one = _dequote_string_literal(t)
    if one is not None:
        try:
            return [labels.index(one) + 1]
        except ValueError:
            return None
    cinfo = parse_call_text(t)
    if cinfo is not None and cinfo[0].lower() == "c":
        vals = cinfo[1] + list(cinfo[2].values())
        out: list[int] = []
        for v in vals:
            lab = _dequote_string_literal(v.strip())
            if lab is None:
                return None
            try:
                out.append(labels.index(lab) + 1)
            except ValueError:
                return None
        return out
    return None


def _named_subscript_lhs_to_fortran(lhs_src: str) -> str | None:
    m = re.match(r"^([A-Za-z]\w*)\s*\[\s*(.+)\s*\]$", lhs_src.strip())
    if m is None:
        return None
    base = m.group(1)
    inner = m.group(2).strip()
    if len(_split_index_dims(inner)) != 1:
        return None
    idx = _name_indices_from_subscript(base, inner)
    if idx is not None:
        if len(idx) == 1:
            return f"{base}({idx[0]})"
        return f"{base}([" + ", ".join(str(i) for i in idx) + "])"
    label = _dequote_string_literal(inner)
    if label is not None and (base == "y" or base.endswith("_result")):
        dynamic = {
            "order": "1",
            "intercept": "2",
            "sigma2": "nacf + 3",
            "aic": "nacf + 4",
            "bic": "nacf + 5",
        }
        if label in dynamic:
            return f"{base}({dynamic[label]})"
    c_inner = parse_call_text(inner)
    if c_inner is not None and (base == "y" or base.endswith("_result")) and c_inner[0].lower() == "paste0" and len(c_inner[1]) >= 2:
        prefix = _dequote_string_literal(c_inner[1][0].strip())
        seq_call = parse_call_text(c_inner[1][1].strip())
        if prefix == "phi" and seq_call is not None and seq_call[0].lower() == "seq_len":
            n_src = seq_call[1][0] if seq_call[1] else seq_call[2].get("n", "")
            if n_src:
                n_f = _int_bound_expr(r_expr_to_fortran(n_src))
                return f"{base}(r_seq_int(3, {n_f} + 2))"
    return None


def _split_sprintf_format(fmt: str) -> tuple[list[str], int]:
    # Split on printf-like conversion specs and return literal pieces + count(specs).
    # Supports common specs used by these scripts (e.g. %d, %.6f, %g).
    spec_re = re.compile(r"%(?:[-+ 0#]*)(?:\d+)?(?:\.\d+)?[a-zA-Z]")
    pieces: list[str] = []
    last = 0
    nspec = 0
    for m in spec_re.finditer(fmt):
        pieces.append(fmt[last : m.start()])
        last = m.end()
        nspec += 1
    pieces.append(fmt[last:])
    return pieces, nspec


def _sprintf_scalar_expr_to_fortran(expr: str) -> str | None:
    ci = parse_call_text(expr.strip())
    if ci is None or ci[0].lower() != "sprintf" or not ci[1]:
        return None
    fmt_raw = _dequote_string_literal(ci[1][0].strip())
    if fmt_raw is None:
        return None
    vals = list(ci[1][1:])
    spec_re = re.compile(r"%(?P<flags>[-+ 0#]*)(?P<width>\d+)?(?:\.(?P<prec>\d+))?(?P<conv>[diufFeEgGs%])")
    out: list[str] = []
    last = 0
    arg_i = 0
    for m in spec_re.finditer(fmt_raw):
        lit = fmt_raw[last:m.start()]
        if lit:
            out.append(_fortran_str_literal(lit))
        conv = m.group("conv")
        if conv == "%":
            out.append(_fortran_str_literal("%"))
        else:
            if arg_i >= len(vals):
                return None
            val_f = r_expr_to_fortran(vals[arg_i].strip())
            arg_i += 1
            if conv in {"d", "i", "u"}:
                out.append(f"int_to_string({_int_bound_expr(val_f)})")
            elif conv in {"f", "F"}:
                digits = int(m.group("prec") or "6")
                out.append(f"real_to_string_f(real({val_f}, kind=dp), {max(0, digits)})")
            elif conv in {"e", "E", "g", "G"}:
                digits = int(m.group("prec") or "0")
                out.append(f"real_to_string_g(real({val_f}, kind=dp), {max(0, digits)})")
            elif conv == "s":
                out.append(r_expr_to_fortran(vals[arg_i - 1].strip()))
            else:
                return None
        last = m.end()
    tail = fmt_raw[last:]
    if tail:
        out.append(_fortran_str_literal(tail))
    if arg_i != len(vals):
        return None
    if not out:
        return '""'
    return " // ".join(out)


def _replace_balanced_func_calls(expr: str, fname: str, repl_fn) -> str:
    """Replace `fname(<arg>)` calls using balanced-parentheses parsing."""
    out: list[str] = []
    i = 0
    n = len(expr)
    fnlow = fname.lower()
    while i < n:
        m = re.search(rf"\b{re.escape(fname)}\b", expr[i:], re.IGNORECASE)
        if m is None:
            out.append(expr[i:])
            break
        s0 = i + m.start()
        e0 = i + m.end()
        if (
            (s0 > 0 and (expr[s0 - 1].isalnum() or expr[s0 - 1] == "_"))
            or (e0 < n and (expr[e0].isalnum() or expr[e0] == "_"))
        ):
            out.append(expr[i:e0])
            i = e0
            continue
        if s0 > 0 and expr[s0 - 1] == ".":
            out.append(expr[i:e0])
            i = e0
            continue
        out.append(expr[i:s0])
        j = e0
        while j < n and expr[j].isspace():
            j += 1
        if j >= n or expr[j] != "(":
            out.append(expr[s0:e0])
            i = e0
            continue
        depth = 0
        in_single = False
        in_double = False
        k = j
        close = -1
        while k < n:
            ch = expr[k]
            if ch == "'" and not in_double:
                in_single = not in_single
            elif ch == '"' and not in_single:
                in_double = not in_double
            elif not in_single and not in_double:
                if ch == "(":
                    depth += 1
                elif ch == ")":
                    depth -= 1
                    if depth == 0:
                        close = k
                        break
            k += 1
        if close < 0:
            out.append(expr[s0:])
            break
        inner = expr[j + 1 : close]
        if fnlow in {"beta", "gamma"} and (
            inner.lstrip().startswith(":")
            or re.search(r",\s*:", inner)
            or re.search(r":\s*,", inner)
        ):
            out.append(expr[s0 : close + 1])
            i = close + 1
            continue
        out.append(repl_fn(inner))
        i = close + 1
    return "".join(out)


def _display_expr_to_fortran(expr: str) -> str:
    """Lower display-oriented R wrappers (sprintf/paste) to printable Fortran expr."""
    s = expr.strip()
    cinfo = parse_call_text(s)
    if cinfo is not None:
        nm, pos, kw = cinfo
        low = nm.lower()
        if low == "length" and pos:
            arg = pos[0].strip()
            if re.fullmatch(r"[A-Za-z]\w*(?:\.[A-Za-z]\w*)*", arg):
                return f"size({_sanitize_r_var_name(arg)})"
        if low == "sprintf":
            if len(pos) >= 2:
                return r_expr_to_fortran(pos[1])
            if len(pos) == 1:
                return r_expr_to_fortran(pos[0])
        if low == "paste":
            # Common case: paste(sprintf(fmt, arr), collapse=" ")
            if pos:
                inner = pos[0].strip()
                c2 = parse_call_text(inner)
                if c2 is not None and c2[0].lower() == "sprintf":
                    p2 = c2[1]
                    if len(p2) >= 2:
                        return r_expr_to_fortran(p2[1])
                return r_expr_to_fortran(inner)
    return r_expr_to_fortran(s)


def _format_vec_call_from_paste(expr: str) -> str | None:
    """Lower paste(sprintf("%.<digits>f", x), collapse=sep) to a helper."""
    ci = parse_call_text(expr.strip())
    if ci is None or ci[0].lower() != "paste":
        return None
    pos = ci[1]
    kw = ci[2]
    if not pos:
        return None
    collapse = kw.get("collapse")
    if collapse is None or _dequote_string_literal(collapse.strip()) is None:
        return None
    sp = parse_call_text(pos[0].strip())
    if sp is None or sp[0].lower() != "sprintf" or len(sp[1]) < 2:
        return None
    fmt_src = sp[1][0].strip()
    val_src = sp[1][1].strip()
    digits_src = "6"
    fmt_literal = _dequote_string_literal(fmt_src)
    if fmt_literal is not None:
        m_fmt = re.match(r"^%\.(\d+)f$", fmt_literal)
        if m_fmt is not None:
            digits_src = m_fmt.group(1)
    fmt_call = parse_call_text(fmt_src)
    if fmt_call is not None and fmt_call[0].lower() == "paste0" and len(fmt_call[1]) >= 3:
        parts = fmt_call[1]
        if _dequote_string_literal(parts[0].strip()) == "%." and _dequote_string_literal(parts[2].strip()) == "f":
            digits_src = parts[1].strip()
    val_f = r_expr_to_fortran(val_src)
    digits_f = _int_bound_expr(r_expr_to_fortran(digits_src))
    sep_f = r_expr_to_fortran(collapse.strip())
    return f"r_format_vec(real({val_f}, kind=dp), {digits_f}, {sep_f})"


def _expr_returns_character(expr: str) -> bool:
    """Conservative character-scalar result test for function returns."""
    t = expr.strip()
    if _dequote_string_literal(t) is not None:
        return True
    if _format_vec_call_from_paste(t) is not None:
        return True
    if re.fullmatch(r"(?:colnames|rownames|names)\s*\(.+\)\s*\[[^\]]+\]", t, re.IGNORECASE):
        return True
    ci = parse_call_text(t)
    if ci is None:
        return False
    return ci[0].lower() in {
        "paste",
        "paste0",
        "sprintf",
        "format",
        "as.character",
        "sub",
        "substr",
        "getwd",
        "mode",
        "colnames",
        "rownames",
        "names",
    }


def _character_array_literal_expr(labels: list[str]) -> str:
    if not labels:
        return "[character(len=1) :: ]"
    width = max(1, max(len(str(x)) for x in labels))
    vals = ", ".join('"' + str(x).replace('"', '""') + '"' for x in labels)
    return f"[character(len={width}) :: {vals}]"


def _character_label_select_expr(labels: list[str], idx_expr: str) -> str:
    vals = [str(x) for x in labels]
    if not vals:
        return '""'
    width = max(1, max(len(x) for x in vals))
    quoted = ['"' + x.ljust(width).replace('"', '""') + '"' for x in vals]
    out = quoted[-1]
    for i, val in reversed(list(enumerate(quoted[:-1], start=1))):
        out = f"merge({val}, {out}, ({idx_expr}) == {i})"
    return out


def _r_mode_literal_for_expr(expr: str) -> str:
    """Return an R mode(...) string literal for expressions we can classify."""
    txt = expr.strip()
    txt_l = txt.lower()
    simple = re.fullmatch(r"[A-Za-z]\w*(?:\.[A-Za-z]\w*)*", txt)
    simple_name = _sanitize_r_var_name(txt).lower() if simple else ""
    call = parse_call_text(txt)
    call_name = call[0].lower() if call is not None else ""
    if _dequote_string_literal(txt) is not None or call_name == "character" or simple_name in _KNOWN_CHAR_VECTOR_NAMES:
        return '"character"'
    if txt_l in {"true", "false", "t", "f"} or call_name == "logical" or simple_name in _KNOWN_LOGICAL_VECTOR_NAMES:
        return '"logical"'
    if call_name == "c":
        vals = list(call[1]) + list(call[2].values()) if call is not None else []
        if vals and all(_dequote_string_literal(v.strip()) is not None for v in vals):
            return '"character"'
        if vals and all(v.strip().lower() in {"true", "false", "t", "f"} for v in vals):
            return '"logical"'
        return '"numeric"'
    if (
        _is_int_literal(txt)
        or _is_real_literal(txt)
        or call_name in {"numeric", "double", "integer", "seq", "seq.int", "seq_len", "runif", "rnorm"}
        or simple_name in (_KNOWN_VECTOR_NAMES | _KNOWN_INT_VECTOR_NAMES | _CURRENT_INT_ARRAY_NAMES)
    ):
        return '"numeric"'
    return '"numeric"'


def _sprintf_arg_items(expr: str) -> list[str] | None:
    """Lower sprintf(fmt, ...) into printable Fortran item expressions."""
    ci = parse_call_text(expr.strip())
    if ci is None or ci[0].lower() != "sprintf":
        return None
    pos = ci[1]
    if not pos:
        return []
    fmt_raw = _dequote_string_literal(pos[0])
    vals = [r_expr_to_fortran(a) for a in pos[1:]]
    if fmt_raw is None:
        return vals
    pieces, nspec = _split_sprintf_format(fmt_raw)
    out_items: list[str] = []
    nuse = min(nspec, len(vals))
    for i in range(nuse + 1):
        lit = pieces[i].replace("\\n", "").replace("\\t", " ")
        if lit:
            out_items.append(_fortran_str_literal(lit))
        if i < nuse:
            out_items.append(vals[i])
    if nuse < len(vals):
        out_items.extend(vals[nuse:])
    return out_items


def strip_r_comment(line: str) -> str:
    out = []
    in_single = False
    in_double = False
    esc = False
    for ch in line:
        if esc:
            out.append(ch)
            esc = False
            continue
        if ch == "\\":
            out.append(ch)
            esc = True
            continue
        if ch == "'" and not in_double:
            in_single = not in_single
            out.append(ch)
            continue
        if ch == '"' and not in_single:
            in_double = not in_double
            out.append(ch)
            continue
        if ch == "#" and not in_single and not in_double:
            break
        out.append(ch)
    return "".join(out).rstrip()


def split_r_code_comment(line: str) -> tuple[str, str]:
    """Split R source line into code and trailing `#` comment (outside strings)."""
    out = []
    in_single = False
    in_double = False
    esc = False
    for i, ch in enumerate(line):
        if esc:
            out.append(ch)
            esc = False
            continue
        if ch == "\\":
            out.append(ch)
            esc = True
            continue
        if ch == "'" and not in_double:
            in_single = not in_single
            out.append(ch)
            continue
        if ch == '"' and not in_single:
            in_double = not in_double
            out.append(ch)
            continue
        if ch == "#" and not in_single and not in_double:
            return "".join(out), line[i + 1 :]
        out.append(ch)
    return "".join(out), ""


def extract_r_top_comments(src: str) -> list[str]:
    """Collect leading top-of-file R comments (before first code statement)."""
    out: list[str] = []
    seen_code = False
    for raw in src.splitlines():
        code, cmt = split_r_code_comment(raw)
        tcode = code.strip()
        tcmt = cmt.strip()
        if tcode:
            seen_code = True
            break
        if tcmt:
            if tcmt.startswith("!"):
                continue
            out.append(tcmt)
    dedup: list[str] = []
    prev = None
    for c in out:
        if c != prev:
            dedup.append(c)
        prev = c
    return dedup


def _normalize_r_code_key(code: str) -> str:
    return re.sub(r"\s+", " ", code.strip())


def build_r_comment_lookup(src: str) -> dict[str, list[str]]:
    out: dict[str, list[str]] = {}
    for raw in src.splitlines():
        code, cmt = split_r_code_comment(raw)
        tcode = code.strip()
        tcmt = cmt.strip()
        if not tcode:
            continue
        if tcmt:
            out.setdefault(_normalize_r_code_key(tcode), []).append(tcmt)
    return out


def pop_comment_for_code(code: str, lookup: dict[str, list[str]] | None) -> str:
    if not lookup:
        return ""
    key = _normalize_r_code_key(code)
    arr = lookup.get(key)
    if not arr:
        return ""
    c = arr.pop(0).strip()
    if not arr:
        lookup.pop(key, None)
    return c


def split_top_level_commas(s: str) -> list[str]:
    out: list[str] = []
    cur: list[str] = []
    depth = 0
    bdepth = 0
    cdepth = 0
    in_single = False
    in_double = False
    esc = False
    for ch in s:
        if esc:
            cur.append(ch)
            esc = False
            continue
        if ch == "\\":
            cur.append(ch)
            esc = True
            continue
        if ch == "'" and not in_double:
            in_single = not in_single
            cur.append(ch)
            continue
        if ch == '"' and not in_single:
            in_double = not in_double
            cur.append(ch)
            continue
        if not in_single and not in_double:
            if ch == "(":
                depth += 1
            elif ch == ")" and depth > 0:
                depth -= 1
            elif ch == "[":
                bdepth += 1
            elif ch == "]" and bdepth > 0:
                bdepth -= 1
            elif ch == "{":
                cdepth += 1
            elif ch == "}" and cdepth > 0:
                cdepth -= 1
            elif ch == "," and depth == 0 and bdepth == 0 and cdepth == 0:
                out.append("".join(cur).strip())
                cur = []
                continue
        cur.append(ch)
    tail = "".join(cur).strip()
    if tail:
        out.append(tail)
    return out


def split_top_level_semicolons(s: str) -> list[str]:
    out: list[str] = []
    cur: list[str] = []
    depth = 0
    bdepth = 0
    cdepth = 0
    in_single = False
    in_double = False
    esc = False
    for ch in s:
        if esc:
            cur.append(ch)
            esc = False
            continue
        if ch == "\\":
            cur.append(ch)
            esc = True
            continue
        if ch == "'" and not in_double:
            in_single = not in_single
            cur.append(ch)
            continue
        if ch == '"' and not in_single:
            in_double = not in_double
            cur.append(ch)
            continue
        if not in_single and not in_double:
            if ch == "(":
                depth += 1
            elif ch == ")" and depth > 0:
                depth -= 1
            elif ch == "[":
                bdepth += 1
            elif ch == "]" and bdepth > 0:
                bdepth -= 1
            elif ch == "{":
                cdepth += 1
            elif ch == "}" and cdepth > 0:
                cdepth -= 1
            elif ch == ";" and depth == 0 and bdepth == 0 and cdepth == 0:
                out.append("".join(cur).strip())
                cur = []
                continue
        cur.append(ch)
    tail = "".join(cur).strip()
    if tail:
        out.append(tail)
    return out


def split_top_level_assignment(s: str) -> tuple[str, str] | None:
    """Split `lhs <- rhs` or top-level `lhs = rhs` outside brackets/strings."""
    depth = 0
    bdepth = 0
    cdepth = 0
    in_single = False
    in_double = False
    esc = False
    i = 0
    while i < len(s):
        ch = s[i]
        if esc:
            esc = False
            i += 1
            continue
        if ch == "\\":
            esc = True
            i += 1
            continue
        if ch == "'" and not in_double:
            in_single = not in_single
            i += 1
            continue
        if ch == '"' and not in_single:
            in_double = not in_double
            i += 1
            continue
        if not in_single and not in_double:
            if ch == "(":
                depth += 1
                i += 1
                continue
            if ch == ")" and depth > 0:
                depth -= 1
                i += 1
                continue
            if ch == "[":
                bdepth += 1
                i += 1
                continue
            if ch == "]" and bdepth > 0:
                bdepth -= 1
                i += 1
                continue
            if ch == "{":
                cdepth += 1
                i += 1
                continue
            if ch == "}" and cdepth > 0:
                cdepth -= 1
                i += 1
                continue
            if depth == 0 and bdepth == 0 and cdepth == 0:
                if s.startswith("<-", i):
                    return s[:i].strip(), s[i + 2 :].strip()
                if ch == "=":
                    prev = s[i - 1] if i > 0 else ""
                    nxt = s[i + 1] if i + 1 < len(s) else ""
                    if prev not in {"=", "!", "<", ">"} and nxt != "=":
                        return s[:i].strip(), s[i + 1 :].strip()
        i += 1
    return None


def _contains_superassignment(expr: str) -> bool:
    in_single = False
    in_double = False
    esc = False
    i = 0
    while i < len(expr):
        ch = expr[i]
        if esc:
            esc = False
            i += 1
            continue
        if ch == "\\":
            esc = True
            i += 1
            continue
        if ch == "'" and not in_double:
            in_single = not in_single
            i += 1
            continue
        if ch == '"' and not in_single:
            in_double = not in_double
            i += 1
            continue
        if not in_single and not in_double and expr.startswith("<<-", i):
            return True
        i += 1
    return False


def _expr_has_assign_call(expr: str) -> bool:
    cinfo = parse_call_text(expr.strip())
    if cinfo is not None and cinfo[0].lower() == "assign":
        return True
    found = False

    def repl(_inner: str) -> str:
        nonlocal found
        found = True
        return "assign()"

    _replace_balanced_func_calls(expr, "assign", repl)
    return found


def validate_unsupported_environment_assignment(stmts: list[object]) -> None:
    def check_expr(expr: str) -> None:
        if _contains_superassignment(expr):
            raise NotImplementedError("unsupported superassignment <<-; R environment mutation is not supported")
        if _expr_has_assign_call(expr):
            raise NotImplementedError("unsupported assign(): dynamic/environment assignment is not supported")

    def walk(ss: list[object]) -> None:
        for st in ss:
            if isinstance(st, Assign):
                check_expr(st.expr)
            elif isinstance(st, PrintStmt):
                for a in st.args:
                    check_expr(a)
            elif isinstance(st, CallStmt):
                if st.name.lower() == "assign":
                    raise NotImplementedError("unsupported assign(): dynamic/environment assignment is not supported")
                for a in st.args:
                    check_expr(a)
            elif isinstance(st, ExprStmt):
                check_expr(st.expr)
            elif isinstance(st, IfStmt):
                check_expr(st.cond)
                walk(st.then_body)
                walk(st.else_body)
            elif isinstance(st, ForStmt):
                check_expr(st.iter_expr)
                walk(st.body)
            elif isinstance(st, WhileStmt):
                check_expr(st.cond)
                walk(st.body)
            elif isinstance(st, RepeatStmt):
                walk(st.body)
            elif isinstance(st, FuncDef):
                walk(st.body)

    walk(stmts)


def _split_top_level_pipe(expr: str) -> list[str] | None:
    parts: list[str] = []
    cur: list[str] = []
    depth = 0
    in_single = False
    in_double = False
    esc = False
    i = 0
    while i < len(expr):
        ch = expr[i]
        if esc:
            cur.append(ch)
            esc = False
            i += 1
            continue
        if ch == "\\" and (in_single or in_double):
            cur.append(ch)
            esc = True
            i += 1
            continue
        if ch == "'" and not in_double:
            in_single = not in_single
            cur.append(ch)
            i += 1
            continue
        if ch == '"' and not in_single:
            in_double = not in_double
            cur.append(ch)
            i += 1
            continue
        if not in_single and not in_double:
            if ch in "([":
                depth += 1
            elif ch in ")]" and depth > 0:
                depth -= 1
            if depth == 0 and expr.startswith("|>", i):
                part = "".join(cur).strip()
                if not part:
                    return None
                parts.append(part)
                cur = []
                i += 2
                continue
        cur.append(ch)
        i += 1
    if not parts:
        return None
    tail = "".join(cur).strip()
    if not tail:
        return None
    parts.append(tail)
    return parts


def _lower_r_native_pipe_expr(expr: str) -> str:
    parts = _split_top_level_pipe(expr.strip())
    if parts is None or len(parts) < 2:
        return expr
    acc = parts[0]
    for step in parts[1:]:
        c = parse_call_text(step)
        if c is None:
            raise NotImplementedError("unsupported native pipe expression: right-hand side must be a function call")
        fn, pos, kw = c
        if any(p.strip() == "_" for p in pos) or any(v.strip() == "_" for v in kw.values()):
            pos = [acc if p.strip() == "_" else p for p in pos]
            kw = {k: (acc if v.strip() == "_" else v) for k, v in kw.items()}
        else:
            pos = [acc] + list(pos)
        args = list(pos) + [f"{k} = {v}" for k, v in kw.items()]
        acc = f"{fn}(" + ", ".join(args) + ")"
    return acc


def _r_statement_continues(txt: str) -> bool:
    """Return true when an R physical line clearly needs the next line."""
    t = txt.rstrip()
    if not t:
        return False
    asn = split_top_level_assignment(t)
    if asn is not None:
        rhs = asn[1].strip()
        ih = _parse_if_head(rhs)
        if ih is not None and not ih[1].strip():
            return True
    return re.search(r"(?:<-|=|,|%\*%|%%|%/%|\|>|[+\-*/^]|&&|\|\||&|\|)\s*$", t) is not None


def _find_unquoted_brace(txt: str) -> int:
    in_single = False
    in_double = False
    esc = False
    for i, ch in enumerate(txt):
        if esc:
            esc = False
            continue
        if ch == "\\" and (in_single or in_double):
            esc = True
            continue
        if ch == "'" and not in_double:
            in_single = not in_single
        elif ch == '"' and not in_single:
            in_double = not in_double
        elif not in_single and not in_double and ch in "{}":
            return i
    return -1


def _lower_trycatch_assignment_blocks(src: str) -> str:
    """Lower simple tryCatch assignment blocks before parser line joining."""
    lines = src.splitlines()
    out: list[str] = []
    i = 0
    start_re = re.compile(r"^(\s*)([A-Za-z]\w*)\s*(<-|=)\s*tryCatch\s*\(\s*\{\s*$", re.IGNORECASE)
    handler_re = re.compile(r"^\s*\}\s*,\s*error\s*=\s*function\s*\([^)]*\)\s*\{\s*$", re.IGNORECASE)
    while i < len(lines):
        m_start = start_re.match(lines[i])
        if m_start is None:
            out.append(lines[i])
            i += 1
            continue

        indent, target = m_start.group(1), m_start.group(2)
        body: list[str] = []
        start_line = lines[i]
        i += 1
        while i < len(lines) and handler_re.match(lines[i]) is None:
            body.append(lines[i])
            i += 1
        if i >= len(lines):
            out.append(start_line)
            out.extend(body)
            continue

        i += 1
        while i < len(lines) and lines[i].strip() != "})":
            i += 1
        if i < len(lines) and lines[i].strip() == "})":
            i += 1

        nonblank = [j for j, ln in enumerate(body) if ln.strip()]
        if not nonblank:
            out.append(f"{indent}{target} <- NA_real_")
            continue
        last_idx = nonblank[-1]
        for j, ln in enumerate(body):
            if j == last_idx:
                out.append(f"{indent}{target} <- {ln.strip()}")
            else:
                out.append(ln)
    return "\n".join(out) + ("\n" if src.endswith("\n") else "")


def preprocess_r_lines(src: str) -> list[str]:
    src = _lower_trycatch_assignment_blocks(src)
    lines0: list[str] = []
    seen_code = False
    for raw in src.splitlines():
        code, cmt = split_r_code_comment(raw)
        tcode = code.strip()
        tcmt = cmt.strip()
        if tcode:
            lines0.append(tcode)
            seen_code = True
        elif tcmt and seen_code:
            lines0.append(_R_COMMENT_SENTINEL + tcmt)
    # Join multiline statements by balanced parentheses and subscripts.
    joined: list[str] = []
    cur = ""
    paren_depth = 0
    bracket_depth = 0
    in_single = False
    in_double = False
    pending_comments: list[str] = []
    for ln in lines0:
        txt = ln.strip()
        if txt.startswith(_R_COMMENT_SENTINEL):
            if cur.strip():
                pending_comments.append(txt)
            else:
                joined.append(txt)
            continue
        if pending_comments and not cur.strip():
            joined.extend(pending_comments)
            pending_comments = []
        if not cur:
            cur = txt
        else:
            cur = cur + " " + txt
        i = 0
        while i < len(txt):
            ch = txt[i]
            if ch == "'" and not in_double:
                in_single = not in_single
            elif ch == '"' and not in_single:
                in_double = not in_double
            elif not in_single and not in_double:
                if ch == "(":
                    paren_depth += 1
                elif ch == ")" and paren_depth > 0:
                    paren_depth -= 1
                elif ch == "[":
                    bracket_depth += 1
                elif ch == "]" and bracket_depth > 0:
                    bracket_depth -= 1
            i += 1
        if (
            paren_depth == 0
            and bracket_depth == 0
            and not in_single
            and not in_double
            and not _r_statement_continues(cur)
        ):
            joined.append(cur)
            cur = ""
            if pending_comments:
                joined.extend(pending_comments)
                pending_comments = []
    if cur.strip():
        joined.append(cur)
    if pending_comments:
        joined.extend(pending_comments)
    lines0 = joined
    out: list[str] = []
    for ln in lines0:
        if ln.startswith(_R_COMMENT_SENTINEL):
            out.append(ln)
            continue
        # split top-level semicolon-separated statements
        semis = split_top_level_semicolons(ln) if ";" in ln else [ln]
        for ln_part in semis:
            cur = ln_part
            # make braces standalone tokens to simplify parsing
            while True:
                i = _find_unquoted_brace(cur)
                if i < 0:
                    break
                left = cur[:i].strip()
                br = cur[i]
                right = cur[i + 1 :].strip()
                if left:
                    out.append(left)
                out.append(br)
                cur = right
            if cur.strip():
                out.append(cur.strip())
    return out


def parse_single_statement(ln: str, *, comment_lookup: dict[str, list[str]] | None = None) -> object:
    ln = ln.strip()
    cmt = pop_comment_for_code(ln, comment_lookup)
    fhead = _parse_for_head(ln)
    if fhead is not None:
        var, itexpr, tail = fhead
        if not tail:
            raise NotImplementedError("for requires body in this subset")
        body = [parse_single_statement(tail, comment_lookup=comment_lookup)]
        return ForStmt(var=var, iter_expr=itexpr, body=body)
    ih = _parse_if_head(ln)
    if ih is not None:
        cond, tail = ih
        if not tail:
            raise NotImplementedError("if requires body in this subset")
        split_tail = _split_top_level_else(" " + tail)
        if split_tail is not None:
            then_body = [parse_single_statement(split_tail[0], comment_lookup=comment_lookup)]
            else_body = [parse_single_statement(split_tail[1], comment_lookup=comment_lookup)]
        else:
            then_body = [parse_single_statement(tail, comment_lookup=comment_lookup)]
            else_body = []
        return IfStmt(cond=cond, then_body=then_body, else_body=else_body)
    wh = _parse_while_head(ln)
    if wh is not None:
        cond, tail = wh
        if not tail:
            raise NotImplementedError("while requires body in this subset")
        body = [parse_single_statement(tail, comment_lookup=comment_lookup)]
        return WhileStmt(cond=cond, body=body)
    if ln == "break":
        return ExprStmt(expr="break", comment=cmt)
    if ln == "next":
        return ExprStmt(expr="next", comment=cmt)
    if ln.startswith("function("):
        raise NotImplementedError("nested/anonymous function definitions not supported")
    m_display = re.match(r"^(print|show)\s*\((.*)\)$", ln, re.IGNORECASE)
    if m_display is not None:
        inner = m_display.group(2).strip()
        args = split_top_level_commas(inner) if inner else []
        return PrintStmt(args=args, comment=cmt)
    m_asn_dot = re.match(rf"^({_R_IDENT_RE})\s*(<-|=)\s*(.+)$", ln)
    if m_asn_dot:
        raw_name = m_asn_dot.group(1)
        name = _sanitize_r_var_name(raw_name)
        if raw_name != name:
            _DOTTED_VAR_RENAMES[raw_name] = name
        rhs = m_asn_dot.group(3).strip()
        return Assign(name=name, expr=rhs, comment=cmt)
    m_asn = re.match(r"^([A-Za-z]\w*)\s*(<-|=)\s*(.+)$", ln)
    if m_asn:
        rhs = m_asn.group(3).strip()
        return Assign(name=m_asn.group(1), expr=rhs, comment=cmt)
    m_asn_any = re.match(
        r"^([A-Za-z]\w*(?:\[[^\]]+\])?(?:\$[A-Za-z]\w*(?:\[[^\]]+\])?)*)\s*(<-|=)\s*(.+)$",
        ln,
    )
    if m_asn_any:
        # Keep non-simple LHS assignments as generic expr statements.
        return ExprStmt(expr=ln, comment=cmt)
    cinfo = parse_call_text(ln)
    if cinfo is not None:
        nm, pos, kw = cinfo
        args = list(pos) + [f"{k}={v}" for k, v in kw.items()]
        if nm.lower() in {"print", "stopifnot", "set.seed", "cat", "stop", "write", "writelines", "write.table"}:
            return CallStmt(name=nm, args=args, comment=cmt)
        return ExprStmt(expr=ln, comment=cmt)
    return ExprStmt(expr=ln, comment=cmt)


def parse_block(
    lines: list[str],
    i0: int = 0,
    *,
    stop_at_rbrace: bool = False,
    comment_lookup: dict[str, list[str]] | None = None,
) -> tuple[list[object], int]:
    stmts: list[object] = []
    i = i0
    while i < len(lines):
        ln = lines[i].strip()
        if ln.startswith(_R_COMMENT_SENTINEL):
            txt = ln[len(_R_COMMENT_SENTINEL) :].strip()
            if txt:
                stmts.append(CommentStmt(text=txt))
            i += 1
            continue
        if ln == "}" or (stop_at_rbrace and ln.lower().startswith("} else")):
            if stop_at_rbrace:
                if ln.lower().startswith("} else"):
                    lines[i] = ln[2:].strip()
                    return stmts, i
                return stmts, i + 1
            i += 1
            continue
        if ln == "{":
            i += 1
            continue

        wh = _parse_while_head(ln)
        if wh is not None:
            cond, tail = wh
            if tail:
                if tail == "{":
                    i += 1
                    body, i = parse_block(lines, i, stop_at_rbrace=True, comment_lookup=comment_lookup)
                else:
                    body = [parse_single_statement(tail, comment_lookup=comment_lookup)]
                    i += 1
            else:
                i += 1
                if i < len(lines) and lines[i].strip() == "{":
                    body, i = parse_block(lines, i + 1, stop_at_rbrace=True, comment_lookup=comment_lookup)
                else:
                    if i >= len(lines):
                        raise NotImplementedError("while missing body")
                    body = [parse_single_statement(lines[i], comment_lookup=comment_lookup)]
                    i += 1
            stmts.append(WhileStmt(cond=cond, body=body))
            continue

        if ln.startswith("repeat"):
            tail = ln[len("repeat") :].strip()
            if tail:
                if tail == "{":
                    i += 1
                    body, i = parse_block(lines, i, stop_at_rbrace=True, comment_lookup=comment_lookup)
                else:
                    body = [parse_single_statement(tail, comment_lookup=comment_lookup)]
                    i += 1
            else:
                i += 1
                if i < len(lines) and lines[i].strip() == "{":
                    body, i = parse_block(lines, i + 1, stop_at_rbrace=True, comment_lookup=comment_lookup)
                else:
                    if i >= len(lines):
                        raise NotImplementedError("repeat missing body")
                    body = [parse_single_statement(lines[i], comment_lookup=comment_lookup)]
                    i += 1
            stmts.append(RepeatStmt(body=body))
            continue

        fhead = _parse_for_head(ln)
        if fhead is not None:
            var, itexpr, tail = fhead
            if tail:
                if tail == "{":
                    i += 1
                    body, i = parse_block(lines, i, stop_at_rbrace=True, comment_lookup=comment_lookup)
                else:
                    body = [parse_single_statement(tail, comment_lookup=comment_lookup)]
                    i += 1
                stmts.append(ForStmt(var=var, iter_expr=itexpr, body=body))
                continue
            i += 1
            if i < len(lines) and lines[i].strip() == "{":
                body, i = parse_block(lines, i + 1, stop_at_rbrace=True, comment_lookup=comment_lookup)
            else:
                if i >= len(lines):
                    raise NotImplementedError("for missing body")
                body = [parse_single_statement(lines[i], comment_lookup=comment_lookup)]
                i += 1
            stmts.append(ForStmt(var=var, iter_expr=itexpr, body=body))
            continue

        fn_head = _parse_function_assign_head(ln)
        if fn_head is not None:
            fname, arg_txt, fn_tail = fn_head
            args: list[str] = []
            defaults: dict[str, str] = {}
            arg_name_map: dict[str, str] = {}
            if arg_txt:
                for part in split_top_level_commas(arg_txt):
                    pt = part.strip()
                    if pt == "...":
                        args.append(pt)
                        continue
                    m_ap = re.match(r"^([A-Za-z]\w*(?:\.[A-Za-z]\w*)*)\s*=\s*(.+)$", pt)
                    if m_ap:
                        raw_anm = m_ap.group(1)
                        anm = _sanitize_fortran_kwarg_name(raw_anm)
                        if not anm:
                            continue
                        args.append(anm)
                        defaults[anm] = _replace_idents(m_ap.group(2).strip(), arg_name_map)
                        if raw_anm != anm:
                            arg_name_map[raw_anm] = anm
                    else:
                        if re.match(r"^[A-Za-z]\w*(?:\.[A-Za-z]\w*)*$", pt):
                            anm = _sanitize_fortran_kwarg_name(pt)
                            if not anm:
                                continue
                            args.append(anm)
                            if pt != anm:
                                arg_name_map[pt] = anm
                        else:
                            anm = _sanitize_fortran_kwarg_name(pt)
                            if anm:
                                args.append(anm)
            if fn_tail:
                if fn_tail == "{":
                    i += 1
                    body, i = parse_block(lines, i, stop_at_rbrace=True, comment_lookup=comment_lookup)
                else:
                    body = [parse_single_statement(fn_tail, comment_lookup=comment_lookup)]
                    i += 1
            else:
                i += 1
                if i < len(lines) and lines[i].strip() == "{":
                    body, i = parse_block(lines, i + 1, stop_at_rbrace=True, comment_lookup=comment_lookup)
                else:
                    if i >= len(lines):
                        raise NotImplementedError("function missing body in this subset")
                    body = [parse_single_statement(lines[i], comment_lookup=comment_lookup)]
                    i += 1
            if arg_name_map:
                body = [_rename_stmt_obj(st, arg_name_map) for st in body]
            stmts.append(FuncDef(name=fname, args=args, defaults=defaults, body=body))
            continue

        asn_if = split_top_level_assignment(ln)
        if asn_if is not None:
            lhs_if, rhs_if = asn_if[0].strip(), asn_if[1].strip()
            ih_assign = _parse_if_head(rhs_if)
            if ih_assign is not None:
                cond, tail = ih_assign
                then_body_raw: list[object] = []
                else_body_raw: list[object] = []
                if tail:
                    if tail == "{":
                        i += 1
                        then_body_raw, i = parse_block(lines, i, stop_at_rbrace=True, comment_lookup=comment_lookup)
                    else:
                        split_tail = _split_top_level_else(" " + tail)
                        if split_tail is not None:
                            then_body_raw = [parse_single_statement(split_tail[0], comment_lookup=comment_lookup)]
                            else_body_raw = [parse_single_statement(split_tail[1], comment_lookup=comment_lookup)]
                        else:
                            then_body_raw = [parse_single_statement(tail, comment_lookup=comment_lookup)]
                        i += 1
                else:
                    i += 1
                    if i < len(lines) and lines[i].strip() == "{":
                        then_body_raw, i = parse_block(lines, i + 1, stop_at_rbrace=True, comment_lookup=comment_lookup)
                    else:
                        if i >= len(lines):
                            raise NotImplementedError("assignment if missing body")
                        split_next = _split_top_level_else(" " + lines[i].strip())
                        if split_next is not None:
                            then_body_raw = [parse_single_statement(split_next[0], comment_lookup=comment_lookup)]
                            else_body_raw = [parse_single_statement(split_next[1], comment_lookup=comment_lookup)]
                        else:
                            then_body_raw = [parse_single_statement(lines[i], comment_lookup=comment_lookup)]
                        i += 1
                if i < len(lines):
                    else_ln = lines[i].strip()
                    if else_ln in {"else", "else {"}:
                        i += 1
                        if else_ln == "else {":
                            else_body_raw, i = parse_block(lines, i, stop_at_rbrace=True, comment_lookup=comment_lookup)
                        elif i < len(lines) and lines[i].strip() == "{":
                            else_body_raw, i = parse_block(lines, i + 1, stop_at_rbrace=True, comment_lookup=comment_lookup)
                        else:
                            if i >= len(lines):
                                raise NotImplementedError("assignment else missing body")
                            else_body_raw = [parse_single_statement(lines[i], comment_lookup=comment_lookup)]
                            i += 1

                def _branch_as_assignment(branch: list[object]) -> list[object]:
                    if len(branch) != 1:
                        return branch
                    only = branch[0]
                    if isinstance(only, ExprStmt):
                        return [Assign(lhs_if, only.expr, only.comment)]
                    if isinstance(only, Assign):
                        return [Assign(lhs_if, only.expr, only.comment)]
                    return branch

                stmts.append(
                    IfStmt(
                        cond=cond,
                        then_body=_branch_as_assignment(then_body_raw),
                        else_body=_branch_as_assignment(else_body_raw),
                    )
                )
                continue

        ih = _parse_if_head(ln)
        if ih is not None:
            cond, tail = ih
            then_body: list[object] = []
            else_body: list[object] = []
            if tail:
                split_tail = _split_top_level_else(" " + tail)
                if tail == "{":
                    i += 1
                    then_body, i = parse_block(lines, i, stop_at_rbrace=True, comment_lookup=comment_lookup)
                elif split_tail is not None:
                    then_body = [parse_single_statement(split_tail[0], comment_lookup=comment_lookup)]
                    else_body = [parse_single_statement(split_tail[1], comment_lookup=comment_lookup)]
                    i += 1
                else:
                    then_body = [parse_single_statement(tail, comment_lookup=comment_lookup)]
                    i += 1
            else:
                i += 1
                if i < len(lines) and lines[i].strip() == "{":
                    then_body, i = parse_block(lines, i + 1, stop_at_rbrace=True, comment_lookup=comment_lookup)
                else:
                    # accept single next-statement body without braces
                    if i >= len(lines):
                        raise NotImplementedError("if missing body")
                    then_body = [parse_single_statement(lines[i], comment_lookup=comment_lookup)]
                    i += 1
                if i < len(lines) and lines[i].strip() in {"else", "else {"}:
                    else_line = lines[i].strip()
                    i += 1
                    if else_line == "else {":
                        else_body, i = parse_block(lines, i, stop_at_rbrace=True, comment_lookup=comment_lookup)
                    elif i < len(lines) and lines[i].strip() == "{":
                        else_body, i = parse_block(lines, i + 1, stop_at_rbrace=True, comment_lookup=comment_lookup)
                    else:
                        if i >= len(lines):
                            raise NotImplementedError("else missing body")
                        else_body = [parse_single_statement(lines[i], comment_lookup=comment_lookup)]
                        i += 1
                # Support brace-style chained else-if / else blocks:
                #   if (...) { ... } else if (...) { ... } else { ... }
                head_else_if: IfStmt | None = None
                tail_else_if: IfStmt | None = None
                while i < len(lines) and lines[i].strip().lower().startswith("else if"):
                    e_line = lines[i].strip()
                    e_if = _parse_if_head(e_line[len("else ") :].strip())
                    if e_if is None:
                        break
                    e_cond, e_tail = e_if
                    e_then: list[object] = []
                    i += 1
                    if e_tail:
                        if e_tail == "{":
                            e_then, i = parse_block(lines, i, stop_at_rbrace=True, comment_lookup=comment_lookup)
                        else:
                            e_then = [parse_single_statement(e_tail, comment_lookup=comment_lookup)]
                    else:
                        if i < len(lines) and lines[i].strip() == "{":
                            e_then, i = parse_block(lines, i + 1, stop_at_rbrace=True, comment_lookup=comment_lookup)
                        else:
                            if i >= len(lines):
                                raise NotImplementedError("else if missing body")
                            e_then = [parse_single_statement(lines[i], comment_lookup=comment_lookup)]
                            i += 1
                    node = IfStmt(cond=e_cond, then_body=e_then, else_body=[])
                    if head_else_if is None:
                        head_else_if = node
                    if tail_else_if is not None:
                        tail_else_if.else_body = [node]
                    tail_else_if = node

                if head_else_if is not None:
                    else_body = [head_else_if]

                if i < len(lines) and lines[i].strip() in {"else", "else {"}:
                    else_line_final = lines[i].strip()
                    i += 1
                    e_final: list[object] = []
                    if else_line_final == "else {":
                        e_final, i = parse_block(lines, i, stop_at_rbrace=True, comment_lookup=comment_lookup)
                    elif i < len(lines) and lines[i].strip() == "{":
                        e_final, i = parse_block(lines, i + 1, stop_at_rbrace=True, comment_lookup=comment_lookup)
                    else:
                        if i >= len(lines):
                            raise NotImplementedError("else missing body")
                        e_final = [parse_single_statement(lines[i], comment_lookup=comment_lookup)]
                        i += 1
                    if tail_else_if is not None:
                        tail_else_if.else_body = e_final
                    else:
                        else_body = e_final
            stmts.append(IfStmt(cond=cond, then_body=then_body, else_body=else_body))
            continue

        if ln.startswith("list(") and not ln.endswith(")"):
            parts = [ln]
            depth = ln.count("(") - ln.count(")")
            i += 1
            while i < len(lines) and depth > 0:
                part = lines[i].strip()
                parts.append(part)
                depth += part.count("(") - part.count(")")
                i += 1
            stmts.append(ExprStmt(expr=" ".join(parts), comment=""))
            continue

        try:
            st = parse_single_statement(ln, comment_lookup=comment_lookup)
            stmts.append(st)
            i += 1
            continue
        except NotImplementedError as e:
            if "function definitions not yet supported" in str(e):
                raise
            pass

        raise NotImplementedError(f"unrecognized statement: {ln}")
    return stmts, i


def _combine_switch_lines(lines: list[str]) -> list[str]:
    out: list[str] = []
    i = 0
    while i < len(lines):
        line = lines[i]
        if not re.match(r"^\s*switch\s*\(", line, re.IGNORECASE):
            out.append(line)
            i += 1
            continue
        parts = [line]
        depth = line.count("(") - line.count(")")
        i += 1
        while i < len(lines) and depth > 0:
            parts.append(lines[i])
            depth += lines[i].count("(") - lines[i].count(")")
            i += 1
        out.append(" ".join(p.strip() for p in parts if p.strip()))
    return out


def _split_switch_body_lines(body_src: str) -> list[str]:
    txt = body_src.strip()
    if not txt:
        return []
    txt = re.sub(r"\s+(?=[A-Za-z]\w*(?:\[[^\]]+\])?\s*(?:<-|=)\s*)", "\n", txt)
    return [ln.strip() for ln in txt.splitlines() if ln.strip()]


def _parse_switch_case_block(case_src: str) -> tuple[str, list[object]] | None:
    m_case = re.match(r'^\s*("(?:""|[^"])*")\s*=\s*\{(.*)\}\s*$', case_src, re.DOTALL)
    if m_case is None:
        return None
    label_src = m_case.group(1).strip()
    body_src = m_case.group(2).strip()
    body_lines = _split_switch_body_lines(body_src)
    body, idx = parse_block(body_lines, 0)
    if idx != len(body_lines):
        raise NotImplementedError("could not parse switch case body")
    return label_src, body


def _parse_switch_positional_block(case_src: str) -> list[object] | None:
    t_case = case_src.strip()
    if not (t_case.startswith("{") and t_case.endswith("}")):
        return None
    body_lines = _split_switch_body_lines(t_case[1:-1].strip())
    body, idx = parse_block(body_lines, 0)
    if idx != len(body_lines):
        raise NotImplementedError("could not parse switch positional body")
    return body


def _lower_switch_expr_stmt(st: ExprStmt) -> object:
    c_switch = parse_call_text(st.expr.strip())
    if c_switch is None or c_switch[0].lower() != "switch" or not c_switch[1]:
        return st
    selector_src = c_switch[1][0].strip()
    cases: list[tuple[str, list[object]]] = []
    default_body: list[object] = []
    for case_src in c_switch[1][1:]:
        parsed = _parse_switch_case_block(case_src)
        if parsed is not None:
            cases.append(parsed)
            continue
    if cases:
        return SwitchStmt(selector=selector_src, cases=cases, default_body=default_body, selector_kind="character")
    for idx_case, case_src in enumerate(c_switch[1][1:], start=1):
        body = _parse_switch_positional_block(case_src)
        if body is None:
            return st
        cases.append((str(idx_case), body))
    if not cases:
        return st
    return SwitchStmt(selector=selector_src, cases=cases, default_body=default_body, selector_kind="integer")


def _lower_switch_assign_stmt(st: Assign) -> object:
    c_switch = parse_call_text(st.expr.strip())
    if c_switch is None or c_switch[0].lower() != "switch" or not c_switch[1]:
        return st
    selector_src = c_switch[1][0].strip()
    cases: list[tuple[str, list[object]]] = []
    for idx_case, case_src in enumerate(c_switch[1][1:], start=1):
        case_expr = case_src.strip()
        if _parse_switch_case_block(case_expr) is not None or _parse_switch_positional_block(case_expr) is not None:
            return st
        cases.append((str(idx_case), [Assign(st.name, case_expr, st.comment if idx_case == 1 else "")]))
    if not cases:
        return st
    return SwitchStmt(selector=selector_src, cases=cases, default_body=[], selector_kind="integer")


def lower_switch_statements(stmts: list[object]) -> list[object]:
    out: list[object] = []
    for st in stmts:
        if isinstance(st, ExprStmt):
            out.append(_lower_switch_expr_stmt(st))
        elif isinstance(st, Assign):
            out.append(_lower_switch_assign_stmt(st))
        elif isinstance(st, FuncDef):
            out.append(FuncDef(st.name, st.args, st.defaults, lower_switch_statements(st.body)))
        elif isinstance(st, IfStmt):
            out.append(IfStmt(st.cond, lower_switch_statements(st.then_body), lower_switch_statements(st.else_body)))
        elif isinstance(st, SwitchStmt):
            out.append(SwitchStmt(st.selector, [(label, lower_switch_statements(body)) for label, body in st.cases], lower_switch_statements(st.default_body), st.selector_kind))
        elif isinstance(st, ForStmt):
            out.append(ForStmt(st.var, st.iter_expr, lower_switch_statements(st.body)))
        elif isinstance(st, WhileStmt):
            out.append(WhileStmt(st.cond, lower_switch_statements(st.body)))
        elif isinstance(st, RepeatStmt):
            out.append(RepeatStmt(lower_switch_statements(st.body)))
        else:
            out.append(st)
    return out


def infer_assigned_names(stmts: list[object], out: dict[str, int] | None = None) -> dict[str, int]:
    if out is None:
        out = {}
    for st in stmts:
        if isinstance(st, Assign):
            out[st.name] = out.get(st.name, 0) + 1
        elif isinstance(st, ForStmt):
            out[st.var] = out.get(st.var, 0) + 1
            infer_assigned_names(st.body, out)
        elif isinstance(st, WhileStmt):
            infer_assigned_names(st.body, out)
        elif isinstance(st, RepeatStmt):
            infer_assigned_names(st.body, out)
        elif isinstance(st, IfStmt):
            infer_assigned_names(st.then_body, out)
            infer_assigned_names(st.else_body, out)
        elif isinstance(st, SwitchStmt):
            for _label, body in st.cases:
                infer_assigned_names(body, out)
            infer_assigned_names(st.default_body, out)
        elif isinstance(st, FuncDef):
            # separate scope
            continue
    return out


def collect_assignment_comments(stmts: list[object], out: dict[str, str] | None = None) -> dict[str, str]:
    if out is None:
        out = {}
    for st in stmts:
        if isinstance(st, Assign):
            cmt = st.comment.strip()
            if cmt and st.name not in out:
                out[st.name] = cmt
        elif isinstance(st, ForStmt):
            collect_assignment_comments(st.body, out)
        elif isinstance(st, WhileStmt):
            collect_assignment_comments(st.body, out)
        elif isinstance(st, RepeatStmt):
            collect_assignment_comments(st.body, out)
        elif isinstance(st, IfStmt):
            collect_assignment_comments(st.then_body, out)
            collect_assignment_comments(st.else_body, out)
        elif isinstance(st, FuncDef):
            continue
    return out


def attach_function_adjacent_comments(stmts: list[object]) -> list[object]:
    out: list[object] = []
    pending_comments: list[str] = []
    for st in stmts:
        if isinstance(st, CommentStmt):
            pending_comments.append(st.text)
            continue
        if isinstance(st, FuncDef) and pending_comments:
            st = FuncDef(
                name=st.name,
                args=list(st.args),
                defaults=dict(st.defaults),
                body=list(st.body),
                leading_comments=tuple(list(st.leading_comments) + pending_comments),
            )
            pending_comments = []
            out.append(st)
            continue
        if pending_comments:
            out.extend(CommentStmt(text=c) for c in pending_comments)
            pending_comments = []
        out.append(st)
    if pending_comments:
        out.extend(CommentStmt(text=c) for c in pending_comments)
    return out


def _split_top_level_colon(s: str) -> tuple[str, str] | None:
    """Split `a:b` at top level (outside parens/strings), else None."""
    depth = 0
    bdepth = 0
    in_single = False
    in_double = False
    for i, ch in enumerate(s):
        if ch == "'" and not in_double:
            in_single = not in_single
            continue
        if ch == '"' and not in_single:
            in_double = not in_double
            continue
        if in_single or in_double:
            continue
        if ch == "(":
            depth += 1
            continue
        if ch == ")" and depth > 0:
            depth -= 1
            continue
        if ch == "[":
            bdepth += 1
            continue
        if ch == "]" and bdepth > 0:
            bdepth -= 1
            continue
        if ch == ":" and depth == 0 and bdepth == 0:
            # Do not treat namespace operator `::` as sequence colon.
            if (i > 0 and s[i - 1] == ":") or (i + 1 < len(s) and s[i + 1] == ":"):
                continue
            a = s[:i].strip()
            b = s[i + 1 :].strip()
            if a and b:
                return a, b
            return None
    return None


def _split_top_level_token(text: str, token: str, *, from_right: bool = False) -> tuple[str, str] | None:
    """Split `text` at top-level `token` outside (), [], {}, and quotes."""
    def _is_exponent_sign(pos: int) -> bool:
        if token not in {"+", "-"} or pos <= 0 or pos + 1 >= len(text):
            return False
        if text[pos - 1] not in {"e", "E"} or not text[pos + 1].isdigit():
            return False
        return pos >= 2 and (text[pos - 2].isdigit() or text[pos - 2] == ".")
    def _is_unary_sign(pos: int) -> bool:
        if token not in {"+", "-"}:
            return False
        j = pos - 1
        while j >= 0 and text[j].isspace():
            j -= 1
        if j < 0:
            return True
        return text[j] in "([{,=:+-*/^&|!<>~"

    in_single = False
    in_double = False
    esc = False
    pdepth = 0
    bdepth = 0
    cdepth = 0
    hits: list[int] = []
    i = 0
    n = len(text)
    while i < n:
        ch = text[i]
        if esc:
            esc = False
            i += 1
            continue
        if ch == "\\":
            esc = True
            i += 1
            continue
        if ch == "'" and not in_double:
            in_single = not in_single
            i += 1
            continue
        if ch == '"' and not in_single:
            in_double = not in_double
            i += 1
            continue
        if not in_single and not in_double:
            if ch == "(":
                pdepth += 1
                i += 1
                continue
            if ch == ")" and pdepth > 0:
                pdepth -= 1
                i += 1
                continue
            if ch == "[":
                bdepth += 1
                i += 1
                continue
            if ch == "]" and bdepth > 0:
                bdepth -= 1
                i += 1
                continue
            if ch == "{":
                cdepth += 1
                i += 1
                continue
            if ch == "}" and cdepth > 0:
                cdepth -= 1
                i += 1
                continue
            if pdepth == 0 and bdepth == 0 and cdepth == 0 and text.startswith(token, i):
                if _is_exponent_sign(i):
                    i += 1
                    continue
                if _is_unary_sign(i):
                    i += 1
                    continue
                if token == "*" and (
                    (i > 0 and text[i - 1] in {"%", "*"})
                    or (i + 1 < n and text[i + 1] in {"%", "*"})
                ):
                    i += 1
                    continue
                if token == "/" and (
                    (i > 0 and text[i - 1] == "%")
                    or (i + 1 < n and text[i + 1] == "%")
                ):
                    i += 1
                    continue
                hits.append(i)
                i += len(token)
                continue
        i += 1
    if not hits:
        return None
    k = hits[-1] if from_right else hits[0]
    return text[:k].strip(), text[k + len(token) :].strip()


def _split_known_custom_infix_expr(text: str) -> tuple[str, str, str] | None:
    if not _CUSTOM_INFIX_OPS:
        return None
    seen: set[str] = set()
    for op in sorted(_CUSTOM_INFIX_OPS, key=len, reverse=True):
        opl = op.lower()
        if op in seen or opl in seen or opl in {"%%", "%/%", "%*%", "%in%"}:
            continue
        seen.add(op)
        seen.add(opl)
        split = _split_top_level_token(text, op, from_right=True)
        if split is not None:
            lhs, rhs = split
            if lhs.strip() and rhs.strip():
                return op, lhs, rhs
    return None


def _replace_chars_outside_strings(text: str, repl: dict[str, str]) -> str:
    out: list[str] = []
    in_single = False
    in_double = False
    esc = False
    for ch in text:
        if esc:
            out.append(ch)
            esc = False
            continue
        if ch == "\\" and (in_single or in_double):
            out.append(ch)
            esc = True
            continue
        if ch == "'" and not in_double:
            in_single = not in_single
            out.append(ch)
            continue
        if ch == '"' and not in_single:
            in_double = not in_double
            out.append(ch)
            continue
        if not in_single and not in_double and ch in repl:
            out.append(repl[ch])
        else:
            out.append(ch)
    return "".join(out)


def _split_top_level_muldiv_chain(text: str) -> tuple[list[str], list[str]] | None:
    """Split a top-level chain of * and / operators, preserving left-to-right order."""
    in_single = False
    in_double = False
    esc = False
    pdepth = 0
    bdepth = 0
    cdepth = 0
    parts: list[str] = []
    ops: list[str] = []
    start = 0
    i = 0
    while i < len(text):
        ch = text[i]
        if esc:
            esc = False
            i += 1
            continue
        if ch == "\\":
            esc = True
            i += 1
            continue
        if ch == "'" and not in_double:
            in_single = not in_single
            i += 1
            continue
        if ch == '"' and not in_single:
            in_double = not in_double
            i += 1
            continue
        if not in_single and not in_double:
            if ch == "(":
                pdepth += 1
            elif ch == ")" and pdepth > 0:
                pdepth -= 1
            elif ch == "[":
                bdepth += 1
            elif ch == "]" and bdepth > 0:
                bdepth -= 1
            elif ch == "{":
                cdepth += 1
            elif ch == "}" and cdepth > 0:
                cdepth -= 1
            elif pdepth == 0 and bdepth == 0 and cdepth == 0 and ch in {"*", "/"}:
                if ch == "*" and i + 1 < len(text) and text[i + 1] == "*":
                    i += 2
                    continue
                if ch == "*" and i > 0 and text[i - 1] == "*":
                    i += 1
                    continue
                if ch == "*" and ((i > 0 and text[i - 1] == "%") or (i + 1 < len(text) and text[i + 1] == "%")):
                    i += 1
                    continue
                if ch == "/" and ((i > 0 and text[i - 1] == "%") or (i + 1 < len(text) and text[i + 1] == "%")):
                    i += 1
                    continue
                part = text[start:i].strip()
                if not part:
                    return None
                parts.append(part)
                ops.append(ch)
                start = i + 1
        i += 1
    if not ops:
        return None
    tail = text[start:].strip()
    if not tail:
        return None
    parts.append(tail)
    return parts, ops


def _find_top_level_addsub(s: str) -> tuple[int, str] | None:
    """Find first top-level binary + or - (outside parens/strings)."""
    def _is_exponent_sign(pos: int) -> bool:
        if pos <= 0 or pos + 1 >= len(s):
            return False
        if s[pos - 1] not in {"e", "E"} or not s[pos + 1].isdigit():
            return False
        return pos >= 2 and (s[pos - 2].isdigit() or s[pos - 2] == ".")

    depth = 0
    bdepth = 0
    in_single = False
    in_double = False
    prev_nonspace = ""
    for i, ch in enumerate(s):
        if ch == "'" and not in_double:
            in_single = not in_single
            continue
        if ch == '"' and not in_single:
            in_double = not in_double
            continue
        if in_single or in_double:
            continue
        if ch == "(":
            depth += 1
            continue
        if ch == ")" and depth > 0:
            depth -= 1
            continue
        if ch == "[":
            bdepth += 1
            continue
        if ch == "]" and bdepth > 0:
            bdepth -= 1
            continue
        if depth == 0 and bdepth == 0 and ch in {"+", "-"}:
            if _is_exponent_sign(i):
                prev_nonspace = ch
                continue
            # skip unary signs
            if prev_nonspace == "" or prev_nonspace in {"(", ",", ":", "+", "-", "*", "/", "^"}:
                prev_nonspace = ch
                continue
            return i, ch
        if not ch.isspace():
            prev_nonspace = ch
    return None


def _split_index_dims(inner: str) -> list[str]:
    """Split index list by top-level commas, preserving empty dims."""
    out: list[str] = []
    cur: list[str] = []
    depth = 0
    bdepth = 0
    cdepth = 0
    in_single = False
    in_double = False
    esc = False
    for ch in inner:
        if esc:
            cur.append(ch)
            esc = False
            continue
        if ch == "\\":
            cur.append(ch)
            esc = True
            continue
        if ch == "'" and not in_double:
            in_single = not in_single
            cur.append(ch)
            continue
        if ch == '"' and not in_single:
            in_double = not in_double
            cur.append(ch)
            continue
        if not in_single and not in_double:
            if ch == "(":
                depth += 1
            elif ch == ")" and depth > 0:
                depth -= 1
            elif ch == "[":
                bdepth += 1
            elif ch == "]" and bdepth > 0:
                bdepth -= 1
            elif ch == "{":
                cdepth += 1
            elif ch == "}" and cdepth > 0:
                cdepth -= 1
            elif ch == "," and depth == 0 and bdepth == 0 and cdepth == 0:
                out.append("".join(cur).strip())
                cur = []
                continue
        cur.append(ch)
    out.append("".join(cur).strip())
    return out


def _index_inner_1d_to_fortran(inner: str) -> str:
    """Translate one R index expression with R ':' precedence into Fortran."""
    raw_t = inner.strip()
    raw_seq = _split_top_level_colon(raw_t)
    if raw_seq is not None and (raw_seq[0].strip().startswith("(") and raw_seq[0].strip().endswith(")")):
        a, b = raw_seq
        a_f = _int_bound_expr(r_expr_to_fortran(a))
        b_f = _int_bound_expr(r_expr_to_fortran(b))
        return f"r_seq_int({a_f}, {b_f})"
    t = fscan.strip_redundant_outer_parens_expr(raw_t)
    m_lag_upper = re.match(r"^1\s*:\s*([A-Za-z]\w*)\s*-\s*lag$", t, re.IGNORECASE)
    if m_lag_upper is not None:
        return f"1:{_int_bound_expr(r_expr_to_fortran(m_lag_upper.group(1)))} - lag"
    m_lag_lower = re.match(r"^lag\s*\+\s*1\s*:\s*([A-Za-z]\w*)$", t, re.IGNORECASE)
    if m_lag_lower is not None:
        return f"lag + 1:{_int_bound_expr(r_expr_to_fortran(m_lag_lower.group(1)))}"
    # R precedence: ':' binds tighter than +/-. So 2:5-1 means (2:5)-1.
    addsub = _find_top_level_addsub(t)
    if addsub is not None:
        pos, op = addsub
        left = t[:pos].strip()
        right = t[pos + 1 :].strip()
        seq = _split_top_level_colon(left)
        if seq is not None:
            a, b = seq
            a_f = _int_bound_expr(r_expr_to_fortran(a))
            b_f = _int_bound_expr(r_expr_to_fortran(b))
            c_f = _int_bound_expr(r_expr_to_fortran(right))
            return f"(r_seq_int({a_f}, {b_f}) {op} {c_f})"
    seq = _split_top_level_colon(t)
    if seq is not None:
        a, b = seq
        a_f = _int_bound_expr(r_expr_to_fortran(a))
        b_f = _int_bound_expr(r_expr_to_fortran(b))
        m_a_dec = re.fullmatch(r"([A-Za-z]\w*)\s*-\s*(\d+)", a.strip())
        m_b_dec = re.fullmatch(r"([A-Za-z]\w*)\s*-\s*(\d+)", b.strip())
        if m_a_dec is not None and m_b_dec is not None and m_a_dec.group(1) == m_b_dec.group(1):
            if int(m_a_dec.group(2)) < int(m_b_dec.group(2)):
                return f"{a_f}:{b_f}:-1"
        return f"{a_f}:{b_f}"
    m_which = re.match(r"^which\.(min|max)\s*\((.*)\)$", t, re.IGNORECASE)
    if m_which is not None:
        fn = "minloc" if m_which.group(1).lower() == "min" else "maxloc"
        inner = m_which.group(2).strip()
        return f"{fn}({r_expr_to_fortran(inner)}, dim=1)"
    return r_expr_to_fortran(t)


def _index_dim_to_fortran(base: str, dimno: int, d: str) -> str:
    """Translate one dimension subscript with R negative-index semantics."""
    dt = d.strip()
    if dt == "":
        return ":"
    if re.fullmatch(r"[+-]?0+[lL]?", dt) is not None:
        return "1:0"
    dim_labels = _ARRAY_DIM_LABELS.get(base.lower())
    lab_dt = _dequote_string_literal(dt)
    if dim_labels is not None and lab_dt is not None and 1 <= dimno <= len(dim_labels):
        try:
            return str(dim_labels[dimno - 1].index(lab_dt) + 1)
        except ValueError:
            pass
    if dimno == 2 and dt == "price_names" and dt.lower() not in _KNOWN_CHAR_VECTOR_NAMES:
        return "price_names + 1"
    if dimno == 2 and re.fullmatch(r"[A-Za-z]\w*", dt) and dt.lower() in _KNOWN_CHAR_VECTOR_NAMES:
        csv_src = _CSV_HEADER_SOURCES.get(base.lower())
        if csv_src is not None:
            return f"match({dt}, read_csv_header_names({r_expr_to_fortran(csv_src)}))"
    if dimno == 2 and base == "coef_mat":
        lab_dt = _dequote_string_literal(dt)
        coef_idx = {
            "order": "1",
            "intercept": "2",
            "sigma2": "nacf + 3",
            "aic": "nacf + 4",
            "bic": "nacf + 5",
        }
        if lab_dt in coef_idx:
            return coef_idx[lab_dt]
    if re.fullmatch(r"[A-Za-z]\w*", dt) and dt.lower() in _KNOWN_VECTOR_NAMES:
        return dt
    m_seq_len = re.match(r"^r_seq_len\s*\(\s*(.+)\s*\)$", dt, re.IGNORECASE)
    if m_seq_len is not None:
        return f"1:{_int_bound_expr(m_seq_len.group(1).strip())}"
    m_seq_int = re.match(r"^r_seq_int\s*\(\s*([^,]+?)\s*,\s*([^)]+?)\s*\)$", dt, re.IGNORECASE)
    if m_seq_int is not None:
        return f"{_int_bound_expr(m_seq_int.group(1).strip())}:{_int_bound_expr(m_seq_int.group(2).strip())}"
    name_idx = _name_indices_from_subscript(base, dt)
    if name_idx is not None:
        if len(name_idx) == 1:
            return str(name_idx[0])
        return "[" + ", ".join(str(i) for i in name_idx) + "]"
    m_drop_vec = re.match(r"^-\s*c\s*\((.*)\)\s*$", dt, re.IGNORECASE)
    if m_drop_vec:
        parts = split_top_level_commas(m_drop_vec.group(1).strip())
        vals = ", ".join(f"int({r_expr_to_fortran(p.strip())})" for p in parts if p.strip())
        return f"r_drop_indices(r_seq_int(1, size({base}, {dimno})), [{vals}])"
    m_drop_one = re.match(r"^-\s*(.+)$", dt)
    if m_drop_one:
        kf = _int_bound_expr(r_expr_to_fortran(m_drop_one.group(1).strip()))
        return f"r_drop_index(r_seq_int(1, size({base}, {dimno})), {kf})"
    return _index_inner_1d_to_fortran(dt)


def _index_inner_to_fortran(inner: str, base: str | None = None) -> str:
    dims = _split_index_dims(inner)
    dims = [d for d in dims if not re.match(r"^drop\s*=", d.strip(), re.IGNORECASE)]
    if len(dims) <= 1:
        if base is None:
            return _index_inner_1d_to_fortran(dims[0] if dims else "")
        return _index_dim_to_fortran(base, 1, dims[0] if dims else "")
    out_dims: list[str] = []
    for i, d in enumerate(dims, start=1):
        if base is None:
            if d.strip() == "":
                out_dims.append(":")
            else:
                out_dims.append(_index_inner_1d_to_fortran(d))
        else:
            out_dims.append(_index_dim_to_fortran(base, i, d))
    return ", ".join(out_dims)


def _is_int_literal(txt: str) -> bool:
    t = txt.strip()
    return re.match(r"^[+-]?\d+[lL]?(?:_[A-Za-z]\w*)?$", t) is not None


def _is_explicit_r_int_literal(txt: str) -> bool:
    t = txt.strip()
    return re.match(r"^[+-]?\d+[lL](?:_[A-Za-z]\w*)?$", t) is not None


def _normalize_r_int_literal(txt: str) -> str:
    """Convert R integer literal form (e.g., 1000L) to Fortran integer literal."""
    t = txt.strip()
    return re.sub(r"([0-9])[lL](?=(?:_[A-Za-z]\w*)?$)", r"\1", t)


def _int_vector_literal_from_c(expr: str) -> str | None:
    c = parse_call_text(expr.strip())
    if c is None or c[0].lower() != "c":
        return None
    vals = list(c[1]) + list(c[2].values())
    if not vals:
        return "[]"
    out: list[str] = []
    for v in vals:
        t = v.strip()
        if _is_int_literal(t):
            out.append(_normalize_r_int_literal(t))
            continue
        if re.match(r"^[+-]?\d+\.0+(?:[eE]\+?0+)?$", t):
            out.append(str(int(float(t))))
            continue
        return None
    return "[" + ", ".join(out) + "]"


def _strict_int_vector_literal_from_c(expr: str) -> str | None:
    c = parse_call_text(expr.strip())
    if c is None or c[0].lower() != "c":
        return None
    vals = list(c[1]) + list(c[2].values())
    if not vals:
        return "[]"
    out: list[str] = []
    for v in vals:
        t = v.strip()
        if not _is_int_literal(t):
            return None
        out.append(_normalize_r_int_literal(t))
    return "[" + ", ".join(out) + "]"


def _real_vector_constructor_from_mixed_c(expr: str) -> str | None:
    c = parse_call_text(expr.strip())
    if c is None or c[0].lower() != "c":
        return None
    vals = list(c[1]) + list(c[2].values())
    if not vals:
        return None
    lowered = [r_expr_to_fortran(v.strip()) for v in vals if v.strip()]
    if not lowered:
        return None
    has_real = any(
        re.search(r"\bkind\s*=\s*dp\b|_dp\b", v, re.IGNORECASE)
        or re.match(r"^[A-Za-z]\w*$", v.strip()) and v.strip().lower() in _KNOWN_VECTOR_NAMES - {
            x.lower() for x in _KNOWN_LOGICAL_VECTOR_NAMES
        }
        for v in lowered
    )
    has_int_vec = any(re.match(r"^[A-Za-z]\w*$", v.strip()) and v.strip().lower() not in _KNOWN_VECTOR_NAMES for v in lowered)
    if not has_real or not has_int_vec:
        return None
    return "[" + ", ".join(f"real({v}, kind=dp)" for v in lowered) + "]"


def _coerce_array_constructor_real(expr: str) -> str:
    t = expr.strip()
    if not (t.startswith("[") and t.endswith("]")):
        return expr
    parts = split_top_level_commas(t[1:-1])
    if not parts:
        return expr
    return "[" + ", ".join(f"real({p.strip()}, kind=dp)" for p in parts if p.strip()) + "]"


def _parse_matrix_dim2(expr: str) -> tuple[str, str] | None:
    """Parse a 2-element matrix-dimension expression like c(2,3) or [2,3]."""
    if not expr:
        return None
    t = expr.strip()
    parts: list[str] | None = None
    cinfo = parse_call_text(t)
    if cinfo is not None and cinfo[0].lower() == "c":
        vals = cinfo[1] + list(cinfo[2].values())
        parts = [v.strip() for v in vals if v.strip()]
    elif t.startswith("[") and t.endswith("]"):
        parts = [v.strip() for v in split_top_level_commas(t[1:-1]) if v.strip()]
    else:
        return None
    if len(parts) != 2:
        return None
    if not (_is_integerish_expr_with_names(parts[0]) and _is_integerish_expr_with_names(parts[1])):
        return None
    return parts[0], parts[1]


def _matrix_has_integer_literal_data(expr: str) -> bool:
    cinfo = parse_call_text(expr.strip())
    if cinfo is None or cinfo[0].lower() != "matrix":
        return False
    pos, kw = cinfo[1], cinfo[2]
    data_src = pos[0] if pos else kw.get("data", "")
    data_txt = data_src.strip()
    return (
        _strict_int_vector_literal_from_c(data_txt) is not None
        or _split_top_level_colon(data_txt) is not None
        or data_txt.lower().startswith(("integer(", "r_seq_int(", "r_seq_len(", "r_rep_int("))
    )


def _expr_uses_int64(txt: str) -> bool:
    return re.search(r"\bint64\b|_int64\b", txt, re.IGNORECASE) is not None


def _is_real_literal(txt: str) -> bool:
    t = txt.strip()
    return (
        re.match(r"^[+-]?\d+\.\d*([eE][+-]?\d+)?(?:_[A-Za-z]\w*)?$", t) is not None
        or re.match(r"^[+-]?\d+[eE][+-]?\d+(?:_[A-Za-z]\w*)?$", t) is not None
    )


def _is_integer_arith_expr(txt: str) -> bool:
    """Conservative integer-only arithmetic expression checker (R syntax)."""
    t = txt.strip()
    if not t:
        return False
    if any(ch.isalpha() for ch in t):
        return False
    if "." in t:
        return False
    if re.search(r"\d[eE][+-]?\d", t):
        return False
    if re.search(r"[^0-9\+\-\*/\^\(\)\s]", t):
        return False
    return re.search(r"\d", t) is not None


def _is_integerish_expr_with_names(txt: str) -> bool:
    t = re.sub(r"(?<=\d)[lL]\b", "", txt.strip())
    if not t:
        return False
    if re.search(r"(?<![A-Za-z_])(?:\d+\.\d*|\.\d+)(?:[eEdD][+-]?\d+)?", t):
        return False
    if re.search(r"\d[eE][+-]?\d", t):
        return False
    if re.search(r"[^A-Za-z0-9_\.\+\-\*/\^\(\)\s]", t):
        return False
    return re.search(r"[A-Za-z0-9_]", t) is not None


def _integerish_expr_names(txt: str) -> set[str] | None:
    """Return sanitized names in an integer-looking expression, or None if unsafe."""
    t = re.sub(r"(?<=\d)[lL]\b", "", txt.strip())
    if not _is_integerish_expr_with_names(t):
        return None
    if "/" in t:
        return None
    names = {
        _sanitize_r_var_name(nm)
        for nm in re.findall(r"\b[A-Za-z]\w*(?:\.[A-Za-z]\w*)*\b", t)
    }
    return names


def _sort_parameter_pairs_by_dependencies(pairs: list[tuple[str, str]]) -> list[tuple[str, str]]:
    """Topologically order Fortran parameter declarations by same-block deps."""
    remaining = {k: v for k, v in pairs}
    ordered: list[tuple[str, str]] = []
    while remaining:
        progressed = False
        for k, v in list(remaining.items()):
            deps = {
                _sanitize_r_var_name(nm)
                for nm in re.findall(r"\b[A-Za-z]\w*(?:\.[A-Za-z]\w*)*\b", v)
            } & set(remaining)
            deps.discard(k)
            if deps:
                continue
            ordered.append((k, v))
            del remaining[k]
            progressed = True
        if not progressed:
            ordered.extend(remaining.items())
            break
    return ordered


def _contains_name(expr: str, name: str) -> bool:
    return re.search(rf"\b{re.escape(name)}\b", expr) is not None


def _ifelse_integer_coded(rhs: str) -> bool:
    m = re.match(r"^ifelse\s*\(\s*.+\s*,\s*([^,]+)\s*,\s*([^)]+)\s*\)\s*$", rhs.strip())
    if not m:
        return False
    a = m.group(1).strip()
    b = m.group(2).strip()
    return _is_int_literal(a) and _is_int_literal(b)


def infer_integer_context_names(stmts: list[object]) -> set[str]:
    """Infer scalar names used in integer-only contexts such as sizes and indices."""
    out: set[str] = set()

    def mark_expr(expr: str) -> None:
        t = expr.strip()
        if not t:
            return
        t = _strip_named_actual_value(t)
        if _is_int_literal(t) or _is_real_literal(t):
            return
        if parse_call_text(t) is not None:
            return
        if _is_integerish_expr_with_names(t):
            for nm in re.findall(r"\b[A-Za-z]\w*(?:\.[A-Za-z]\w*)*\b", t):
                out.add(_sanitize_r_var_name(nm))

    def mark_call_args(txt: str) -> None:
        for m in re.finditer(r"\bseq_len\s*\(\s*([^()]+)\s*\)", txt, re.IGNORECASE):
            mark_expr(m.group(1))
        for m in re.finditer(r"\b(?:r_seq_len|r_seq_int_by|r_seq_int_length)\s*\(\s*([^()]+)\s*\)", txt, re.IGNORECASE):
            mark_expr(m.group(1))
        c = parse_call_text(txt.strip())
        if c is None:
            return
        nm, pos, kw = c
        key = nm.lower()
        for arg in [*pos, *kw.values()]:
            mark_call_args(arg)

        def pos_arg(i: int) -> str | None:
            return pos[i] if len(pos) > i else None

        if key in {"matrix", "array"}:
            for src in [kw.get("nrow"), kw.get("ncol"), pos_arg(1), pos_arg(2)]:
                if src is not None:
                    mark_expr(src)
            dim_src = kw.get("dim")
            if dim_src is not None:
                c_dim = parse_call_text(dim_src.strip())
                if c_dim is not None and c_dim[0].lower() == "c":
                    for p in c_dim[1]:
                        mark_expr(p)
                else:
                    mark_expr(dim_src)
        elif key == "vector":
            src = kw.get("length") or pos_arg(1)
            if src is not None:
                mark_expr(src)
        elif key in {"rep", "rep.int", "r_rep_real", "r_rep_int", "r_rep_char"}:
            for src in [kw.get("times"), kw.get("each"), kw.get("length.out"), kw.get("length_out")]:
                if src is not None:
                    mark_expr(src)
        elif key == "sample.int":
            src = kw.get("n") or pos_arg(0)
            if src is not None:
                mark_expr(src)
            src = kw.get("size") or pos_arg(1)
            if src is not None:
                mark_expr(src)
        elif key == "sample":
            src = kw.get("size") or pos_arg(1)
            if src is not None:
                mark_expr(src)
        elif key in {
            "runif", "rnorm", "rgamma", "rbeta", "rchisq", "rf", "rlogis", "rlnorm",
            "rweibull", "rcauchy", "rgeom", "rnbinom", "rhyper", "rwilcox",
            "rsignrank", "rpois", "rbinom", "numeric", "integer", "double",
            "logical", "character", "raw",
        }:
            src = kw.get("n") or pos_arg(0)
            if src is not None:
                mark_expr(src)
        elif key in _USER_FUNC_ARG_KIND:
            arg_kinds = _USER_FUNC_ARG_KIND.get(key, [])
            arg_index = _USER_FUNC_ARG_INDEX.get(key, {})
            for i, kind in enumerate(arg_kinds):
                if kind not in {"int", "integer"}:
                    continue
                src = pos_arg(i)
                if src is None:
                    for arg_nm, idx in arg_index.items():
                        if idx == i:
                            src = kw.get(arg_nm)
                            break
                if src is not None:
                    mark_expr(src)
        elif key == "kmeans":
            for src in [kw.get("centers"), kw.get("nstart")]:
                if src is not None:
                    mark_expr(src)
        elif key in {"seq", "seq.int"}:
            for src in [kw.get("length.out"), kw.get("length_out")]:
                if src is not None:
                    mark_expr(src)

    def mark_indices(txt: str) -> None:
        for m in re.finditer(r"\b[A-Za-z]\w*(?:\$[A-Za-z]\w*)?\s*(?:\[\[|\[)\s*([^\]]+)\s*\]?\]", txt):
            inner = m.group(1)
            for dim in _split_index_dims(inner):
                d = dim.strip()
                if not d or d == ":" or re.match(r"^drop\s*=", d, re.IGNORECASE):
                    continue
                if any(op in d for op in ["==", "!=", ">=", "<=", ">", "<"]):
                    continue
                ab = _split_top_level_colon(d)
                if ab is not None:
                    mark_expr(ab[0])
                    mark_expr(ab[1])
                else:
                    mark_expr(d)

    def mark_integer_modulus_operands(txt: str) -> None:
        for m in re.finditer(r"\b([A-Za-z]\w*)\s*(?:%%|%/%)\s*(-?\d+[lL]?)\b", txt):
            out.add(m.group(1))
        for m in re.finditer(r"\b(-?\d+[lL]?)\s*(?:%%|%/%)\s*([A-Za-z]\w*)\b", txt):
            out.add(m.group(2))

    def scan_text(txt: str) -> None:
        mark_call_args(txt)
        mark_indices(txt)
        mark_integer_modulus_operands(txt)

    def walk(ss: list[object]) -> None:
        for st in ss:
            if isinstance(st, Assign):
                scan_text(st.expr)
                mark_indices(st.name)
            elif isinstance(st, ExprStmt):
                scan_text(st.expr)
            elif isinstance(st, PrintStmt):
                for a in st.args:
                    scan_text(a)
            elif isinstance(st, CallStmt):
                scan_text(st.name + "(" + ", ".join(st.args) + ")")
            elif isinstance(st, ForStmt):
                it = st.iter_expr.strip()
                c_it = parse_call_text(it)
                if c_it is not None and c_it[0].lower() in {"seq_len", "seq_along"} and c_it[1]:
                    mark_expr(c_it[1][0])
                ab = _split_top_level_colon(it)
                if ab is not None:
                    mark_expr(ab[0])
                    mark_expr(ab[1])
                walk(st.body)
            elif isinstance(st, IfStmt):
                scan_text(st.cond)
                walk(st.then_body)
                walk(st.else_body)
            elif isinstance(st, WhileStmt):
                scan_text(st.cond)
                walk(st.body)
            elif isinstance(st, RepeatStmt):
                walk(st.body)

    walk(stmts)
    return out


def _return_call_arg(expr: str) -> str | None:
    c = parse_call_text(expr.strip())
    if c is None or c[0].lower() != "return":
        return None
    if not c[1]:
        return ""
    return c[1][0].strip()


def _function_returns_invisible(fn: FuncDef) -> bool:
    if not fn.body or not isinstance(fn.body[-1], ExprStmt):
        return False
    expr = fn.body[-1].expr.strip()
    ret_arg = _return_call_arg(expr)
    target = ret_arg if ret_arg is not None else expr
    c = parse_call_text((target or "").strip())
    return c is not None and c[0].lower() == "invisible"


def _function_declared_double_args(fn: FuncDef) -> set[str]:
    out: set[str] = set()
    for txt in _collect_stmt_expr_texts(fn.body):
        if "declare" not in txt.lower() or "double" not in txt.lower():
            continue
        for m in re.finditer(r"\b([A-Za-z]\w*)\s*=\s*double\s*\(", txt, re.IGNORECASE):
            out.add(m.group(1))
    return out


def _r_expression_inner(expr: str) -> str | None:
    c = parse_call_text(expr.strip())
    if c is None or c[0].lower() != "expression" or not c[1]:
        return None
    if len(c[1]) != 1 or c[2]:
        raise NotImplementedError("unsupported expression(): only a single unnamed expression is currently supported")
    return c[1][0].strip()


def _is_symbolic_object_expr(expr: str) -> bool:
    c = parse_call_text(expr.strip())
    return c is not None and c[0].lower() in {"expression", "d"}


def _drop_symbolic_object_assignments(stmts: list[object]) -> list[object]:
    out: list[object] = []
    for st in stmts:
        if isinstance(st, Assign) and _is_symbolic_object_expr(st.expr):
            continue
        if isinstance(st, FuncDef):
            out.append(FuncDef(st.name, list(st.args), dict(st.defaults), _drop_symbolic_object_assignments(st.body), st.leading_comments))
        elif isinstance(st, IfStmt):
            out.append(IfStmt(st.cond, _drop_symbolic_object_assignments(st.then_body), _drop_symbolic_object_assignments(st.else_body)))
        elif isinstance(st, ForStmt):
            out.append(ForStmt(st.var, st.iter_expr, _drop_symbolic_object_assignments(st.body)))
        elif isinstance(st, WhileStmt):
            out.append(WhileStmt(st.cond, _drop_symbolic_object_assignments(st.body)))
        elif isinstance(st, RepeatStmt):
            out.append(RepeatStmt(_drop_symbolic_object_assignments(st.body)))
        else:
            out.append(st)
    return out


def _symbolic_paren(expr: str) -> str:
    t = expr.strip()
    if re.fullmatch(r"[A-Za-z]\w*(?:%[A-Za-z]\w*)?(?:\([^()]*\))?", t) or _is_int_literal(t) or _is_real_literal(t):
        return t
    return f"({t})"


def _symbolic_derivative_fortran(expr: str, var: str) -> str:
    t = fscan.strip_redundant_outer_parens_expr(expr.strip())
    if not t:
        raise NotImplementedError("unsupported D() expression: empty expression")
    if t == var:
        return "1.0_dp"
    if _is_int_literal(t) or _is_real_literal(t):
        return "0.0_dp"
    if re.fullmatch(r"[A-Za-z]\w*", t):
        return "0.0_dp"
    if t.startswith("-"):
        return f"(-{_symbolic_paren(_symbolic_derivative_fortran(t[1:].strip(), var))})"

    for op in ["+", "-"]:
        mm = _split_top_level_token(t, op, from_right=True)
        if mm is not None and mm[0].strip():
            lhs, rhs = mm[0].strip(), mm[1].strip()
            dl = _symbolic_derivative_fortran(lhs, var)
            dr = _symbolic_derivative_fortran(rhs, var)
            return f"{_symbolic_paren(dl)} {op} {_symbolic_paren(dr)}"

    mm = _split_top_level_token(t, "*", from_right=True)
    if mm is not None:
        lhs, rhs = mm[0].strip(), mm[1].strip()
        lf, rf = r_expr_to_fortran(lhs), r_expr_to_fortran(rhs)
        dl, dr = _symbolic_derivative_fortran(lhs, var), _symbolic_derivative_fortran(rhs, var)
        return f"{_symbolic_paren(dl)} * {_symbolic_paren(rf)} + {_symbolic_paren(lf)} * {_symbolic_paren(dr)}"

    mm = _split_top_level_token(t, "/", from_right=True)
    if mm is not None:
        lhs, rhs = mm[0].strip(), mm[1].strip()
        lf, rf = r_expr_to_fortran(lhs), r_expr_to_fortran(rhs)
        dl, dr = _symbolic_derivative_fortran(lhs, var), _symbolic_derivative_fortran(rhs, var)
        return f"(({_symbolic_paren(dl)} * {_symbolic_paren(rf)} - {_symbolic_paren(lf)} * {_symbolic_paren(dr)}) / ({_symbolic_paren(rf)}**2))"

    mm = _split_top_level_token(t, "^", from_right=True)
    if mm is not None:
        lhs, rhs = mm[0].strip(), mm[1].strip()
        if not (_is_int_literal(rhs) or _is_real_literal(rhs)):
            raise NotImplementedError("unsupported D() expression: only constant exponents are supported")
        n_f = r_expr_to_fortran(rhs)
        n_minus_1 = str(float(rhs.rstrip("Ll")) - 1.0) + "_dp" if _is_int_literal(rhs) else f"(({n_f}) - 1.0_dp)"
        lf = r_expr_to_fortran(lhs)
        dl = _symbolic_derivative_fortran(lhs, var)
        return f"{_symbolic_paren(n_f)} * {_symbolic_paren(lf)}**{_symbolic_paren(n_minus_1)} * {_symbolic_paren(dl)}"

    c = parse_call_text(t)
    if c is not None:
        fn = c[0].lower()
        if len(c[1]) != 1 or c[2]:
            raise NotImplementedError(f"unsupported D() expression: function `{c[0]}` arguments are not supported")
        inner = c[1][0].strip()
        inner_f = r_expr_to_fortran(inner)
        din = _symbolic_derivative_fortran(inner, var)
        if fn == "sin":
            return f"cos({_symbolic_paren(inner_f)}) * {_symbolic_paren(din)}"
        if fn == "cos":
            return f"(-sin({_symbolic_paren(inner_f)}) * {_symbolic_paren(din)})"
        if fn == "tan":
            return f"(({_symbolic_paren(din)}) / (cos({_symbolic_paren(inner_f)})**2))"
        if fn == "exp":
            return f"exp({_symbolic_paren(inner_f)}) * {_symbolic_paren(din)}"
        if fn == "log":
            return f"({_symbolic_paren(din)} / {_symbolic_paren(inner_f)})"
        if fn == "sqrt":
            return f"({_symbolic_paren(din)} / (2.0_dp * sqrt({_symbolic_paren(inner_f)})))"
        if fn == "gamma":
            return f"gamma({_symbolic_paren(inner_f)}) * r_digamma(real({_symbolic_paren(inner_f)}, kind=dp)) * {_symbolic_paren(din)}"
        if fn in {"lgamma", "log_gamma"}:
            return f"r_digamma(real({_symbolic_paren(inner_f)}, kind=dp)) * {_symbolic_paren(din)}"
        if fn == "erf":
            return f"(2.0_dp / sqrt(acos(-1.0_dp))) * exp(-({_symbolic_paren(inner_f)})**2) * {_symbolic_paren(din)}"
        if fn == "erfc":
            return f"(-(2.0_dp / sqrt(acos(-1.0_dp))) * exp(-({_symbolic_paren(inner_f)})**2) * {_symbolic_paren(din)})"
        if fn == "sinpi":
            return f"acos(-1.0_dp) * cos(acos(-1.0_dp) * real({_symbolic_paren(inner_f)}, kind=dp)) * {_symbolic_paren(din)}"
        if fn == "cospi":
            return f"(-acos(-1.0_dp) * sin(acos(-1.0_dp) * real({_symbolic_paren(inner_f)}, kind=dp)) * {_symbolic_paren(din)})"
        if fn == "tanpi":
            return f"(acos(-1.0_dp) * {_symbolic_paren(din)} / (cos(acos(-1.0_dp) * real({_symbolic_paren(inner_f)}, kind=dp))**2))"
        raise NotImplementedError(f"unsupported D() expression: function `{c[0]}` is not supported")

    raise NotImplementedError(
        "unsupported symbolic derivative expression in D(): only arithmetic expressions in one variable "
        "with +, -, *, /, ^, sin, cos, tan, exp, log, sqrt, gamma, lgamma/log_gamma, erf, erfc, "
        "sinpi, cospi, and tanpi are currently supported"
    )


def _collect_symbolic_derivatives(stmts: list[object]) -> tuple[dict[str, str], dict[str, str]]:
    exprs: dict[str, str] = {}
    derivs: dict[str, str] = {}

    def walk(ss: list[object]) -> None:
        for st in ss:
            if isinstance(st, Assign):
                rhs = st.expr.strip()
                inner = _r_expression_inner(rhs)
                if inner is not None:
                    exprs[st.name] = inner
                    continue
                c = parse_call_text(rhs)
                if c is not None and c[0].lower() == "d":
                    target_src = c[1][0].strip() if c[1] else c[2].get("expr", "").strip()
                    var_src = c[1][1].strip() if len(c[1]) >= 2 else c[2].get("name", c[2].get("var", "")).strip()
                    var_name = _dequote_string_literal(var_src) or var_src
                    expr_src = _r_expression_inner(target_src) if target_src else None
                    if expr_src is None and target_src in exprs:
                        expr_src = exprs[target_src]
                    if expr_src is None:
                        raise NotImplementedError("unsupported D() expression: derivative target is not a known expression() object")
                    derivs[st.name] = _symbolic_derivative_fortran(expr_src, var_name)
            elif isinstance(st, FuncDef):
                walk(st.body)
            elif isinstance(st, IfStmt):
                walk(st.then_body)
                walk(st.else_body)
            elif isinstance(st, ForStmt):
                walk(st.body)
            elif isinstance(st, WhileStmt):
                walk(st.body)
            elif isinstance(st, RepeatStmt):
                walk(st.body)

    walk(stmts)
    return exprs, derivs


def remove_unused_iso_fortran_env_dp_imports(lines: list[str]) -> list[str]:
    """Remove `dp => real64` imports from scopes that do not use `dp`."""
    out = list(lines)
    remove_lines: set[int] = set()

    def code_only(ln: str) -> str:
        return ln.split("!", 1)[0]

    def scope_end(start: int) -> int:
        unit_kind = ""
        for j in range(start - 1, -1, -1):
            txt = code_only(out[j]).strip()
            if not txt:
                continue
            m = re.match(r"^(module|program|subroutine|function)\s+([A-Za-z]\w*)\b", txt, re.IGNORECASE)
            if m is not None and not re.match(r"^module\s+procedure\b", txt, re.IGNORECASE):
                unit_kind = m.group(1).lower()
            break
        if not unit_kind:
            return len(out)
        pat = re.compile(rf"^\s*end\s+{re.escape(unit_kind)}\b", re.IGNORECASE)
        for j in range(start + 1, len(out)):
            if pat.search(code_only(out[j])):
                return j
        return len(out)

    for i, ln in enumerate(out):
        m = re.match(r"^(\s*use\s*,\s*intrinsic\s*::\s*iso_fortran_env\s*,\s*only\s*:\s*)(.*)$", code_only(ln), re.IGNORECASE)
        if m is None:
            continue
        end = scope_end(i)
        body = "\n".join(
            code_only(out[j])
            for j in range(i + 1, end)
            if not re.match(r"^\s*use\s*,\s*intrinsic\s*::\s*iso_fortran_env\b", code_only(out[j]), re.IGNORECASE)
        )
        if re.search(r"\bdp\b", body):
            continue
        imports = [p.strip() for p in m.group(2).split(",") if p.strip()]
        imports = [p for p in imports if not re.match(r"^dp\s*(?:=>\s*real64)?$", p, re.IGNORECASE)]
        if imports:
            out[i] = m.group(1) + ", ".join(imports)
        else:
            remove_lines.add(i)
    return [ln for idx, ln in enumerate(out) if idx not in remove_lines]


def add_missing_iso_fortran_env_dp_imports(lines: list[str]) -> list[str]:
    """Add `dp => real64` imports to scopes that use dp but lack the import."""
    out = list(lines)

    def code_only(ln: str) -> str:
        return ln.split("!", 1)[0]

    def find_scope_end(start: int, unit_kind: str) -> int:
        pat = re.compile(rf"^\s*end\s+{re.escape(unit_kind)}\b", re.IGNORECASE)
        for j in range(start + 1, len(out)):
            if pat.search(code_only(out[j])):
                return j
        return len(out)

    i = 0
    while i < len(out):
        txt = code_only(out[i]).strip()
        m = re.match(r"^(module|program|subroutine|function)\s+([A-Za-z]\w*)\b", txt, re.IGNORECASE)
        if m is None or re.match(r"^module\s+procedure\b", txt, re.IGNORECASE):
            i += 1
            continue
        unit_kind = m.group(1).lower()
        end = find_scope_end(i, unit_kind)
        scope_txt = "\n".join(code_only(out[j]) for j in range(i + 1, end))
        if not re.search(r"\bkind\s*=\s*dp\b|_dp\b", scope_txt, re.IGNORECASE):
            i += 1
            continue
        has_dp_import = False
        for j in range(i + 1, end):
            ln = code_only(out[j])
            if re.match(r"^\s*implicit\s+none\b", ln, re.IGNORECASE):
                break
            m_use = re.match(r"^(\s*use\s*,\s*intrinsic\s*::\s*iso_fortran_env\s*,\s*only\s*:\s*)(.*)$", ln, re.IGNORECASE)
            if m_use is not None and re.search(r"\bdp\b", m_use.group(2), re.IGNORECASE):
                has_dp_import = True
                break
        if has_dp_import:
            i += 1
            continue
        insert_at = i + 1
        while insert_at < end and (
            not code_only(out[insert_at]).strip()
            or re.match(r"^\s*use\b", code_only(out[insert_at]), re.IGNORECASE)
            or code_only(out[insert_at - 1]).rstrip().endswith("&")
        ):
            insert_at += 1
        out.insert(insert_at, "use, intrinsic :: iso_fortran_env, only: dp => real64")
        i = insert_at + 1
    return out


def remove_redundant_procedure_iso_fortran_env_dp_imports(lines: list[str]) -> list[str]:
    """Remove procedure-local dp imports already provided by the enclosing module."""
    out = list(lines)
    remove: set[int] = set()

    def code_only(ln: str) -> str:
        return ln.split("!", 1)[0]

    module_re = re.compile(r"^\s*module\s+[A-Za-z]\w*\b(?!\s*procedure\b)", re.IGNORECASE)
    end_module_re = re.compile(r"^\s*end\s+module\b", re.IGNORECASE)
    contains_re = re.compile(r"^\s*contains\s*$", re.IGNORECASE)
    proc_re = re.compile(
        r"^\s*(?:(?:pure|elemental|impure|recursive|module)\s+)*(?:function|subroutine)\b",
        re.IGNORECASE,
    )
    end_proc_re = re.compile(r"^\s*end\s+(?:function|subroutine)\b", re.IGNORECASE)
    iso_dp_re = re.compile(
        r"^\s*use\s*,\s*intrinsic\s*::\s*iso_fortran_env\s*,\s*only\s*:\s*dp\s*=>\s*real64\s*$",
        re.IGNORECASE,
    )
    iso_any_dp_re = re.compile(
        r"^\s*use\s*,\s*intrinsic\s*::\s*iso_fortran_env\s*,\s*only\s*:\s*(?P<imports>.+)$",
        re.IGNORECASE,
    )

    i = 0
    while i < len(out):
        if module_re.match(code_only(out[i]).strip()) is None:
            i += 1
            continue
        mod_start = i
        j = i + 1
        contains_idx = -1
        mod_end = len(out)
        while j < len(out):
            txt = code_only(out[j]).strip()
            if contains_re.match(txt):
                contains_idx = j
            if end_module_re.match(txt):
                mod_end = j
                break
            j += 1
        if contains_idx < 0:
            i = mod_end + 1
            continue

        module_has_dp = False
        for k in range(mod_start + 1, contains_idx):
            m_use = iso_any_dp_re.match(code_only(out[k]).strip())
            if m_use is not None and re.search(r"\bdp\s*=>\s*real64\b|\bdp\b", m_use.group("imports"), re.IGNORECASE):
                module_has_dp = True
                break
        if not module_has_dp:
            i = mod_end + 1
            continue

        k = contains_idx + 1
        while k < mod_end:
            if proc_re.match(code_only(out[k]).strip()) is None:
                k += 1
                continue
            p = k + 1
            while p < mod_end and end_proc_re.match(code_only(out[p]).strip()) is None:
                if iso_dp_re.match(code_only(out[p]).strip()) is not None:
                    remove.add(p)
                p += 1
            k = p + 1
        i = mod_end + 1

    return [ln for idx, ln in enumerate(out) if idx not in remove]


def coerce_user_call_integer_actuals_by_decl(lines: list[str]) -> list[str]:
    """Coerce simple integer scalar actuals passed to real user-function dummies."""
    out = list(lines)

    def code_only(ln: str) -> str:
        return ln.split("!", 1)[0]

    def collect_integer_names(start: int, end: int) -> set[str]:
        names: set[str] = set()
        for ln in out[start:end]:
            code = code_only(ln)
            m = re.match(r"^\s*integer\b[^:]*::\s*(.+)$", code, re.IGNORECASE)
            if m is None:
                continue
            for part in split_top_level_commas(m.group(1)):
                lhs = part.split("=", 1)[0].strip()
                lhs = re.sub(r"\(.*\)$", "", lhs).strip()
                if re.match(r"^[A-Za-z]\w*$", lhs):
                    names.add(lhs.lower())
        return names

    def find_scope_end(start: int, unit_kind: str) -> int:
        pat = re.compile(rf"^\s*end\s+{re.escape(unit_kind)}\b", re.IGNORECASE)
        for j in range(start + 1, len(out)):
            if pat.search(code_only(out[j])):
                return j
        return len(out)

    def collect_module_spec_integer_names() -> set[str]:
        names: set[str] = set()
        i_mod = 0
        while i_mod < len(out):
            txt_mod = code_only(out[i_mod]).strip()
            if not re.match(r"^module\s+[A-Za-z]\w*\b", txt_mod, re.IGNORECASE) or re.match(
                r"^module\s+procedure\b", txt_mod, re.IGNORECASE
            ):
                i_mod += 1
                continue
            end_mod = find_scope_end(i_mod, "module")
            contains_idx = end_mod
            for k_mod in range(i_mod + 1, end_mod):
                if re.match(r"^\s*contains\b", code_only(out[k_mod]).strip(), re.IGNORECASE):
                    contains_idx = k_mod
                    break
            names.update(collect_integer_names(i_mod + 1, contains_idx))
            i_mod = end_mod + 1
        return names

    module_int_names = collect_module_spec_integer_names()

    def logical_statement_at(start: int, end: int) -> tuple[str, int] | None:
        code = code_only(out[start]).rstrip()
        if not code.strip():
            return None
        if not code.rstrip().endswith("&"):
            return code, start
        pieces = [re.sub(r"&\s*$", "", code).rstrip()]
        j_stmt = start + 1
        while j_stmt < end:
            nxt = code_only(out[j_stmt]).strip()
            if nxt.startswith("&"):
                nxt = nxt[1:].lstrip()
            continued = nxt.rstrip().endswith("&")
            if continued:
                nxt = re.sub(r"&\s*$", "", nxt).rstrip()
            pieces.append(nxt)
            if not continued:
                return " ".join(p for p in pieces if p), j_stmt
            j_stmt += 1
        return " ".join(p for p in pieces if p), min(j_stmt - 1, len(out) - 1)

    i = 0
    while i < len(out):
        txt = code_only(out[i]).strip()
        m_scope = re.match(r"^(module|program|subroutine|function)\s+([A-Za-z]\w*)\b", txt, re.IGNORECASE)
        if m_scope is None or re.match(r"^module\s+procedure\b", txt, re.IGNORECASE):
            i += 1
            continue
        unit_kind = m_scope.group(1).lower()
        end = find_scope_end(i, unit_kind)
        int_names = collect_integer_names(i + 1, end) | module_int_names
        if int_names:
            def coerce_call(fn_name: str, inner: str) -> str:
                kinds = _USER_FUNC_ARG_KIND.get(fn_name.lower())
                if not kinds or "real" not in kinds:
                    return f"{fn_name}({inner})"
                idx_map = _USER_FUNC_ARG_INDEX.get(fn_name.lower(), {})
                parts = split_top_level_commas(inner)
                out_parts: list[str] = []
                pos_i = 0
                for p in parts:
                    ps = p.strip()
                    m_kw = re.match(r"^([A-Za-z]\w*)\s*=\s*(.+)$", ps, re.DOTALL)
                    if m_kw is not None:
                        key = _sanitize_fortran_kwarg_name(m_kw.group(1)).lower()
                        val = m_kw.group(2).strip()
                        idx = idx_map.get(key, -1)
                        if idx >= 0 and idx < len(kinds) and kinds[idx] == "real" and val.lower() in int_names:
                            val = f"real({val}, kind=dp)"
                        out_parts.append(f"{m_kw.group(1)}={val}")
                        continue
                    if pos_i < len(kinds) and kinds[pos_i] == "real" and ps.lower() in int_names:
                        ps = f"real({ps}, kind=dp)"
                    out_parts.append(ps)
                    pos_i += 1
                return f"{fn_name}({', '.join(out_parts)})"

            j = i + 1
            while j < end:
                stmt_info = logical_statement_at(j, end)
                if stmt_info is None:
                    j += 1
                    continue
                code, stmt_end = stmt_info
                if not code.strip() or re.match(
                    r"^\s*(?:(?:pure|elemental|recursive)\s+)*(?:!|use\b|implicit\s+none\b|integer\b|real\b|logical\b|character\b|complex\b|type\b|class\b|"
                    r"module\b|program\b|subroutine\b|function\b|end\b)",
                    code,
                    re.IGNORECASE,
                ):
                    j = stmt_end + 1
                    continue
                new_code = code
                for fn_name in sorted(_USER_FUNC_ARG_KIND, key=len, reverse=True):
                    new_code = _replace_balanced_func_calls(
                        new_code,
                        fn_name,
                        lambda inner, fn_name=fn_name: coerce_call(fn_name, inner),
                    )
                if new_code != code:
                    suffix = ""
                    if stmt_end == j and "!" in out[j]:
                        suffix = "!" + out[j].split("!", 1)[1]
                    out[j] = new_code.rstrip() + (" " + suffix if suffix else "")
                    for k in range(j + 1, stmt_end + 1):
                        out[k] = ""
                j = stmt_end + 1
        i = end + 1
    return out


def _factor_rep_string_info(expr: str) -> tuple[list[str], str] | None:
    """Recognize factor(rep(c("A", ...), each = n)) as integer-coded levels."""
    c_factor = parse_call_text(expr.strip())
    if c_factor is None or c_factor[0].lower() != "factor" or not c_factor[1]:
        return None
    inner = c_factor[1][0].strip()
    c_rep = parse_call_text(inner)
    if c_rep is None or c_rep[0].lower() != "rep" or not c_rep[1]:
        return None
    labels = _parse_string_c_vector(c_rep[1][0].strip())
    if labels is None:
        return None
    each_src = c_rep[2].get("each")
    if each_src is None and len(c_rep[1]) >= 3:
        # rep(x, times, each) positional form.
        each_src = c_rep[1][2]
    if each_src is None:
        return None
    return labels, each_src.strip()


def _factor_sample_string_labels(expr: str) -> list[str] | None:
    """Recognize factor(sample(c("A", ...), ...)) as integer-coded levels."""
    c_factor = parse_call_text(expr.strip())
    if c_factor is None or c_factor[0].lower() != "factor" or not c_factor[1]:
        return None
    inner = c_factor[1][0].strip()
    c_sample = parse_call_text(inner)
    if c_sample is None or c_sample[0].lower() != "sample":
        return None
    x_src = c_sample[1][0] if c_sample[1] else c_sample[2].get("x")
    if x_src is None:
        return None
    return _parse_string_c_vector(x_src.strip())


def classify_vars(
    stmts: list[object], assign_counts: dict[str, int], known_arrays: set[str] | None = None
) -> tuple[set[str], set[str], set[str], set[str], dict[str, str]]:
    ints: set[str] = set()
    real_scalars: set[str] = set()
    int_arrays: set[str] = set()
    real_arrays: set[str] = set()
    params: dict[str, str] = {}
    known_arrays = set(known_arrays or set())
    assigned_names_ctx = set(assign_counts.keys())
    loop_mutated_names = {nm for nm in assigned_names_ctx if _name_assigned_inside_loop(stmts, nm)}
    integer_context_names = infer_integer_context_names(stmts) & assigned_names_ctx
    find_char_arrays = {x.lower() for x in infer_main_character_arrays(stmts)}

    def seed_sequence_assignments(ss: list[object]) -> None:
        for st in ss:
            if isinstance(st, Assign):
                rhs_seed = st.expr.strip()
                rhs_seed_f = r_expr_to_fortran(rhs_seed)
                bare_rhs_sequence = (
                    (_split_top_level_colon(rhs_seed) is not None)
                    and ("[" not in rhs_seed)
                    and ("]" not in rhs_seed)
                    and all(_split_top_level_token(rhs_seed, op, from_right=True) is None for op in ("+", "-", "*", "/"))
                )
                if (
                    bare_rhs_sequence
                    or re.match(r"^(?:r_seq_int|r_seq_len|r_seq_int_by|r_seq_int_length)\s*\(", rhs_seed_f, re.IGNORECASE)
                ):
                    int_arrays.add(st.name)
                    known_arrays.add(st.name)
                    params.pop(st.name, None)
                    ints.discard(st.name)
                    real_arrays.discard(st.name)
                    real_scalars.discard(st.name)
                elif re.match(r"^(?:r_seq_real_by|r_seq_real_length)\s*\(", rhs_seed_f, re.IGNORECASE):
                    real_arrays.add(st.name)
                    known_arrays.add(st.name)
                    params.pop(st.name, None)
                    ints.discard(st.name)
                    int_arrays.discard(st.name)
                    real_scalars.discard(st.name)
                elif re.search(r"\br_seq_(?:int|len|int_by|int_length)\s*\(", rhs_seed_f, re.IGNORECASE) and re.search(
                    r"(?:_dp\b|\d+\.\d*|\.\d+|real\s*\()", rhs_seed_f, re.IGNORECASE
                ):
                    real_arrays.add(st.name)
                    known_arrays.add(st.name)
                    params.pop(st.name, None)
                    ints.discard(st.name)
                    int_arrays.discard(st.name)
                    real_scalars.discard(st.name)
            elif isinstance(st, FuncDef):
                seed_sequence_assignments(st.body)
            elif isinstance(st, IfStmt):
                seed_sequence_assignments(st.then_body)
                seed_sequence_assignments(st.else_body)
            elif isinstance(st, SwitchStmt):
                for _label, body in st.cases:
                    seed_sequence_assignments(body)
                seed_sequence_assignments(st.default_body)
            elif isinstance(st, (ForStmt, WhileStmt, RepeatStmt)):
                seed_sequence_assignments(st.body)

    seed_sequence_assignments(stmts)

    def mark_array_uses(txt: str) -> None:
        for m in re.finditer(r"\b([A-Za-z]\w*)\s*\[", txt):
            nm = m.group(1)
            known_arrays.add(nm)
            if nm in int_arrays:
                # Preserve integer-array classification once established.
                real_arrays.discard(nm)
            else:
                real_arrays.add(nm)
            real_scalars.discard(nm)
            ints.discard(nm)
            params.pop(nm, None)

    def mark_loop_scalar(nm: str, *, integer: bool) -> None:
        if integer:
            ints.add(nm)
            real_scalars.discard(nm)
        else:
            real_scalars.add(nm)
            ints.discard(nm)
        int_arrays.discard(nm)
        real_arrays.discard(nm)
        known_arrays.discard(nm)
        params.pop(nm, None)

    def walk(ss: list[object]) -> None:
        for st in ss:
            if isinstance(st, ForStmt):
                it = st.iter_expr.strip()
                mark_array_uses(it)
                collapsed_vector_print_loop = (
                    re.match(r"^[A-Za-z]\w*$", it) and _is_print_only_loop_over_value(st.body, st.var, exact_var_only=True)
                )
                if collapsed_vector_print_loop:
                    walk(st.body)
                    continue
                if re.match(r"^seq_len\s*\(", it) or re.match(r"^.+:.+$", it):
                    mark_loop_scalar(st.var, integer=True)
                elif re.match(r"^[A-Za-z]\w*$", it):
                    if it in int_arrays:
                        mark_loop_scalar(st.var, integer=True)
                    else:
                        mark_loop_scalar(st.var, integer=False)
                else:
                    mark_loop_scalar(st.var, integer=True)
                walk(st.body)
            elif isinstance(st, WhileStmt):
                mark_array_uses(st.cond)
                walk(st.body)
            elif isinstance(st, RepeatStmt):
                walk(st.body)
            elif isinstance(st, IfStmt):
                mark_array_uses(st.cond)
                walk(st.then_body)
                walk(st.else_body)
            elif isinstance(st, SwitchStmt):
                mark_array_uses(st.selector)
                for _label, body in st.cases:
                    walk(body)
                walk(st.default_body)
            elif isinstance(st, Assign):
                rhs = st.expr.strip()
                rhs_l = rhs.lower()
                c_symbolic = parse_call_text(rhs)
                if c_symbolic is not None and c_symbolic[0].lower() in {"expression", "d"}:
                    params.pop(st.name, None)
                    known_arrays.discard(st.name)
                    ints.discard(st.name)
                    real_scalars.discard(st.name)
                    int_arrays.discard(st.name)
                    real_arrays.discard(st.name)
                    continue
                rhs_f = r_expr_to_fortran(rhs)
                rhs_call_src = re.sub(r"\bt\.test\s*\(", "t_test(", rhs, flags=re.IGNORECASE)
                cinfo = parse_call_text(rhs_call_src)
                mark_array_uses(rhs)
                if _ifelse_integer_coded(rhs):
                    int_arrays.add(st.name)
                    known_arrays.add(st.name)
                    params.pop(st.name, None)
                    ints.discard(st.name)
                    real_arrays.discard(st.name)
                    real_scalars.discard(st.name)
                elif re.match(r"^[A-Za-z]\w*(?:\$[A-Za-z]\w*)?\s*\[\s*[A-Za-z]\w*\s*\]\s*$", rhs):
                    if any(re.match(rf"^{re.escape(a)}\s*\[", rhs) for a in int_arrays):
                        ints.add(st.name)
                        real_scalars.discard(st.name)
                    else:
                        real_scalars.add(st.name)
                        ints.discard(st.name)
                    params.pop(st.name, None)
                    known_arrays.discard(st.name)
                    int_arrays.discard(st.name)
                    real_arrays.discard(st.name)
                elif re.match(r"^[A-Za-z]\w*\s*\[.*(?:==|!=|>=|<=|>|<|:|seq_len\s*\(|c\s*\().*\]\s*$", rhs, re.IGNORECASE):
                    real_arrays.add(st.name)
                    known_arrays.add(st.name)
                    params.pop(st.name, None)
                    ints.discard(st.name)
                    int_arrays.discard(st.name)
                    real_scalars.discard(st.name)
                elif _factor_rep_string_info(rhs) is not None:
                    int_arrays.add(st.name)
                    known_arrays.add(st.name)
                    params.pop(st.name, None)
                    ints.discard(st.name)
                    real_arrays.discard(st.name)
                    real_scalars.discard(st.name)
                elif _factor_sample_string_labels(rhs) is not None:
                    int_arrays.add(st.name)
                    known_arrays.add(st.name)
                    params.pop(st.name, None)
                    ints.discard(st.name)
                    real_arrays.discard(st.name)
                    real_scalars.discard(st.name)
                elif rhs.lower().startswith("sample.int("):
                    int_arrays.add(st.name)
                    known_arrays.add(st.name)
                    params.pop(st.name, None)
                    ints.discard(st.name)
                    real_arrays.discard(st.name)
                    real_scalars.discard(st.name)
