    if c_cast0 is not None and c_cast0[0].lower() == "factor" and c_cast0[1]:
        return r_expr_to_fortran(c_cast0[1][0].strip())
    def _arith_known_array_rank(txt: str) -> int:
        t = fscan.strip_redundant_outer_parens_expr(txt.strip())
        if not t:
            return 0
        if re.fullmatch(r"[A-Za-z]\w*", t) and t.lower() in _KNOWN_RANK3_NAMES:
            return 3
        if re.fullmatch(r"[A-Za-z]\w*", t) and t.lower() in _KNOWN_MATRIX_NAMES:
            return 2
        if re.fullmatch(r"[A-Za-z]\w*", t) and t.lower() in _KNOWN_VECTOR_NAMES:
            return 1
        if _looks_matrix_expr(t):
            return 2
        c_direct_probe = parse_call_text(t)
        if c_direct_probe is not None and c_direct_probe[0].lower() in {"matrix", "array"}:
            return 2
        for op_probe in ["+", "-", "*", "/"]:
            mm_probe = _split_top_level_token(t, op_probe, from_right=True)
            if mm_probe is not None:
                return max(_arith_known_array_rank(mm_probe[0]), _arith_known_array_rank(mm_probe[1]))
        c_probe = parse_call_text(t)
        if c_probe is not None:
            nm_probe = c_probe[0].lower()
            arg_ranks = [_arith_known_array_rank(a.strip()) for a in c_probe[1]]
            if nm_probe in {"log", "logb", "log10", "log2", "log1p", "exp", "expm1", "sqrt", "abs"}:
                return max(arg_ranks or [0])
        return 0

    for op_l, op_f in [("||", ".or."), ("&&", ".and."), ("|", ".or."), ("&", ".and.")]:
        mm_logical_early = _split_top_level_token(s, op_l, from_right=True)
        if mm_logical_early is not None:
            lhs_src = mm_logical_early[0].strip()
            rhs_src = mm_logical_early[1].strip()
            if lhs_src and rhs_src:
                return f"{r_expr_to_fortran(lhs_src)} {op_f} {r_expr_to_fortran(rhs_src)}"

    for op_r, op_f in [("==", "=="), ("!=", "/="), (">=", ">="), ("<=", "<="), (">", ">"), ("<", "<")]:
        mm_cmp_early = _split_top_level_token(s, op_r, from_right=True)
        if mm_cmp_early is not None:
            lhs_src = mm_cmp_early[0].strip()
            rhs_src = mm_cmp_early[1].strip()
            lhs_label = _dequote_string_literal(lhs_src)
            rhs_label = _dequote_string_literal(rhs_src)
            if rhs_label is not None and re.fullmatch(r"[A-Za-z]\w*", lhs_src) and lhs_src.lower() in _CATEGORICAL_LABELS:
                labels = _CATEGORICAL_LABELS[lhs_src.lower()]
                if rhs_label in labels:
                    return f"{r_expr_to_fortran(lhs_src)} {op_f} {labels.index(rhs_label) + 1}"
            if lhs_label is not None and re.fullmatch(r"[A-Za-z]\w*", rhs_src) and rhs_src.lower() in _CATEGORICAL_LABELS:
                labels = _CATEGORICAL_LABELS[rhs_src.lower()]
